            alarm.Cause = "ScannerCalibration Mark 찾기가 실패하였습니다. Mark 확인 후 진행 바랍니다.";
            alarm.Source = Name;
            alarm.Grade = "Error";
            m_dicAlarms.Add(alarm.Code, alarm);

        }

