        public enum TickType : int
        {
            TICK_HOME = 0,              //  0 : Initialize
            TICK_MAIN,                  //  1 : Main Cycle
            TICK_SUB,                   //  2 : Sub Cycle
            TICK_PAUSE,                 //  3 : Pause
            TICK_CHECK,                 //  4 : 체크용 

            TICK_POWERMETER_COMM_BDS,   //  5 : PowerMeter Comm (BDS)
            TICK_POWERMETER_COMM_STAGE, //  6 : PowerMeter Comm (Stage)

            TICK_STAGE_MOVE,            //  7 : Stage Move

            TICK_FLATNESS_MEASURE,       //  8 : Flatness Measure   
            //TICK_LDSZ0,                 //  7 : Loader Stacker Z0
            //TICK_LDSZ1,                 //  8 : Loader Stacker Z1
            //TICK_ULSZ0,                 //  9 : Unloader Stacker Z0
            //TICK_ULSZ1,                 //  10 : Unloader Stacker Z1

            TICK_LASER_FOCUS,           //  11 : Laser Focus 
            TICK_LASER_COMM,            //  12 : Laser Comm 
            TICK_EPRO_COMM,             //  13 : Electro Pneumatic Regulator Comm
            TICK_LASER_HEIGHT_SENSOR,   //  14 : Laser Height Sensor

            TICK_ALIGN,                 //  15 : Align

            TICK_DUSTCOLLECTOR0,        //  16 : Dust Collector (Upper Position)
            TICK_DUSTCOLLECTOR1,        //  17 : Dust Collector (Lower Position)

            //Laser & Scanner Auto Calibration을 위한 Tick 선언
            TICK_LASER_SCANNER_CAL, //  18

            TICK_MAIN_CYCLE_CHECK,  //19 : 1 Cycle Tacktime 계산 
        }

        public int[,] TickCount_Cycle = new int[System.Enum.GetValues(typeof(TickType)).Length, 2];


        public void TickCount_Start(int m_nIndex)
        {
            TickCount_Cycle[m_nIndex, 0] = Environment.TickCount;
        }
        public int TickCount_Elapsed(int m_nIndex)
        {
            int TickCount_Elapsed = 0;
            TickCount_Cycle[m_nIndex, 1] = Environment.TickCount;
            TickCount_Elapsed = TickCount_Cycle[m_nIndex, 1] - TickCount_Cycle[m_nIndex, 0];

            return TickCount_Elapsed;
        }
