        #region Serial Comm. - Illuminator
        public void Illuminator_Init()
        {
            string m_strPortName = "COM1";
            int m_nBaudRate = 9600;
            int m_nDataBits = 8;
            StopBits m_stopBits = StopBits.One;
            Parity m_parity = Parity.None;
            Handshake m_handshake = Handshake.None;

            //  Comm. Port 설정
            m_strPortName = string.Format("COM{0}", Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Serial_CommPort + 1);

            //  Baud Rate 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Serial_CommBaudRate)
            {
                case 0: m_nBaudRate = 1200; break;
                case 1: m_nBaudRate = 2400; break;
                case 2: m_nBaudRate = 4800; break;
                case 3: m_nBaudRate = 9600; break;
                case 4: m_nBaudRate = 19200; break;
                case 5: m_nBaudRate = 38400; break;
                case 6: m_nBaudRate = 57600; break;
                case 7: m_nBaudRate = 115200; break;
                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.Illuminator].Connect)
            {
                Equipment._InitDeviceStatus.Illuminator = false;
                return;
            }

            CommonModule.Instance.Illuminator.Config.PortName = m_strPortName;
            CommonModule.Instance.Illuminator.Config.BaudRate = m_nBaudRate;
            CommonModule.Instance.Illuminator.Config.DataBits = m_nDataBits;
            CommonModule.Instance.Illuminator.Config.StopBits = m_stopBits;
            CommonModule.Instance.Illuminator.Config.Parity = m_parity;
            CommonModule.Instance.Illuminator.Config.Handshake = m_handshake;

            if (CommonModule.Instance.Illuminator.Initialize() != 0)
            {
                Equipment._InitDeviceStatus.Illuminator = false;
                string text = string.Format("{0} Port Open Failed! (Illuminator)", m_strPortName);
                MessageBox.Show(text);
            }

            Equipment._InitDeviceStatus.Illuminator = true;

        }
        #endregion


        #region Serial Comm. - Power Meter (Exit & Target Pos.)

        public void PowerMeterComm_ExitPos_Init()
        {
            string m_strPortName = "COM2";
            int m_nBaudRate = 115200;
            int m_nDataBits = 8;
            StopBits m_stopBits = StopBits.One;
            Parity m_parity = Parity.None;
            Handshake m_handshake = Handshake.None;

            //  Comm. Port 설정
            m_strPortName = string.Format("COM{0}", Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Serial_CommPort + 1);

            //  Baud Rate 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Serial_CommBaudRate)
            {
                case 0: m_nBaudRate = 1200; break;
                case 1: m_nBaudRate = 2400; break;
                case 2: m_nBaudRate = 4800; break;
                case 3: m_nBaudRate = 9600; break;
                case 4: m_nBaudRate = 19200; break;
                case 5: m_nBaudRate = 38400; break;
                case 6: m_nBaudRate = 57600; break;
                case 7: m_nBaudRate = 115200; break;
                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_BDS].Connect)
            {

                Equipment._InitDeviceStatus.PowerMeter_Bds = false;
                return;

            }
            m_powerMeter_ExitPos_Comm = new SerialCommPowerMeter1Port();
            m_powerMeter_ExitPos_Comm.DataReceivedHandler = PowerMeter_ExitPos_DataReceivedHandler;
            m_powerMeter_ExitPos_Comm.DisconnectedHandler = PowerMeter_ExitPos_DisconnectedHandler;
            if (!m_powerMeter_ExitPos_Comm.OpenComm(m_strPortName, m_nBaudRate, m_nDataBits, m_stopBits, m_parity, m_handshake))
            {
                Equipment._InitDeviceStatus.PowerMeter_Bds = false;
                string text = string.Format("{0} Port Open Failed! (Power Meter, Exit Pos.)", m_strPortName);
                MessageBox.Show(text);
                return;
            }

            Equipment._InitDeviceStatus.PowerMeter_Bds = true;
            m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.Start;
        }

        private void PowerMeter_ExitPos_DataReceivedHandler(byte[] receiveData)
        {
            string @string = Encoding.Default.GetString(receiveData);

            m_strLaserPowerMeter_ExitPos_Comm_ReceivedData += @string;

            if (m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Length >= 1)
            {
                if (m_strLaserPowerMeter_ExitPos_Comm_ReceivedData[m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Length - 1] == chrCR)
                {
                    m_bLaserPowerMeter_ExitPos_CommData_Received = true;
                }
                else if (m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Length >= 2)
                {
                    if ((m_strLaserPowerMeter_ExitPos_Comm_ReceivedData[m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Length - 2] == chrCR) &&
                        (m_strLaserPowerMeter_ExitPos_Comm_ReceivedData[m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Length - 1] == chrLF))
                    {
                        m_bLaserPowerMeter_ExitPos_CommData_Received = true;
                    }
                }
            }
        }

        private void PowerMeter_ExitPos_DisconnectedHandler()
        {
            Console.WriteLine("Laser Power Meter serial COM2 disconnected");
        }

