                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_Stage].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_Stage].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_Stage].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_Stage].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.PowerMeter_Stage].Connect)
            {
                Equipment._InitDeviceStatus.PowerMeter_Stage = false;

                return;
            }

            m_powerMeter_TargetPos_Comm = new SerialCommPowerMeter2Port();
            m_powerMeter_TargetPos_Comm.DataReceivedHandler = PowerMeter_TargetPos_DataReceivedHandler;
            m_powerMeter_TargetPos_Comm.DisconnectedHandler = PowerMeter_TargetPos_DisconnectedHandler;
            if (!m_powerMeter_TargetPos_Comm.OpenComm(m_strPortName, m_nBaudRate, m_nDataBits, m_stopBits, m_parity, m_handshake))
            {
                Equipment._InitDeviceStatus.PowerMeter_Stage = false;
                string text = string.Format("{0} Port Open Failed! (Power Meter, Target Pos.)", m_strPortName);
                MessageBox.Show(text);

                return;
            }

            Equipment._InitDeviceStatus.PowerMeter_Stage = true;
            m_nPowerMeterStageCommStep = (int)PowerMeterStageComm_Step.Start;
        }

        private void PowerMeter_TargetPos_DataReceivedHandler(byte[] receiveData)
        {
            string @string = Encoding.Default.GetString(receiveData);

            m_strLaserPowerMeter_TargetPos_Comm_ReceivedData += @string;

            if (m_strLaserPowerMeter_TargetPos_Comm_ReceivedData.Length >= 1)
            {
                if (m_strLaserPowerMeter_TargetPos_Comm_ReceivedData[m_strLaserPowerMeter_TargetPos_Comm_ReceivedData.Length - 1] == chrCR)
                {
                    m_bLaserPowerMeter_TargetPos_CommData_Received = true;
                }
                else if (m_strLaserPowerMeter_TargetPos_Comm_ReceivedData.Length >= 2)
                {
                    if ((m_strLaserPowerMeter_TargetPos_Comm_ReceivedData[m_strLaserPowerMeter_TargetPos_Comm_ReceivedData.Length - 2] == chrCR) &&
                        (m_strLaserPowerMeter_TargetPos_Comm_ReceivedData[m_strLaserPowerMeter_TargetPos_Comm_ReceivedData.Length - 1] == chrLF))
                    {
                        m_bLaserPowerMeter_TargetPos_CommData_Received = true;
                    }
                }
            }
        }

        private void PowerMeter_TargetPos_DisconnectedHandler()
        {
            Console.WriteLine("Laser Power Meter serial COM3 disconnected");
        }

        public bool LaserPowerMeter_GetValue(int m_nPowerMeterPos)
        {
            byte[] m_cSendCmd = new byte[4];
            string m_strSendData = "";

            m_cSendCmd[0] = (byte)'p';
            m_cSendCmd[1] = (byte)'w';
            m_cSendCmd[2] = (byte)'?';
            m_cSendCmd[3] = chrCR;

            m_strSendData = Encoding.Default.GetString(m_cSendCmd);

            if (m_nPowerMeterPos == (int)nPowerMeter.ExitPos)
            {
                if (m_powerMeter_ExitPos_Comm == null)
                    return false;

                if (m_powerMeter_ExitPos_Comm.IsOpen)
                {
                    m_powerMeter_ExitPos_Comm.Send(m_strSendData);

                    return true;
                }

                return false;
            }
            else
            {
                if (m_powerMeter_TargetPos_Comm == null)
                    return false;

                if (m_powerMeter_TargetPos_Comm.IsOpen)
                {
                    m_powerMeter_TargetPos_Comm.Send(m_strSendData);

                    return true;
                }

                return false;
            }
        }

