        public void DustCollector_UpperPos_Comm_Init()
        {
            string m_strPortName = "COM5";
            int m_nBaudRate = 115200;
            int m_nDataBits = 8;
            StopBits m_stopBits = StopBits.One;
            Parity m_parity = Parity.None;
            Handshake m_handshake = Handshake.None;

            //  Comm. Port 설정
            m_strPortName = string.Format("COM{0}", Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Serial_CommPort + 1);

            //  Baud Rate 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Serial_CommBaudRate)
            {
                case 0: m_nBaudRate = 1200; break;
                case 1: m_nBaudRate = 2400; break;
                case 2: m_nBaudRate = 4800; break;
                case 3: m_nBaudRate = 9600; break;
                case 4: m_nBaudRate = 19200; break;
                case 5: m_nBaudRate = 38400; break;
                case 6: m_nBaudRate = 57600; break;
                case 7: m_nBaudRate = 115200; break;
                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Upper].Connect)
                return;

            m_dustCollector_UpperPos_Comm = new SerialCommDustCollector1Port();
            m_dustCollector_UpperPos_Comm.DataReceivedHandler = DustCollector_UpperPos_DataReceivedHandler;
            m_dustCollector_UpperPos_Comm.DisconnectedHandler = DustCollector_UpperPos_DisconnectedHandler;
            if (!m_dustCollector_UpperPos_Comm.OpenComm(m_strPortName, m_nBaudRate, m_nDataBits, m_stopBits, m_parity, m_handshake))
            {
                string text = string.Format("{0} Port Open Failed! (Dust Collector, Upper Pos.)", m_strPortName);
                MessageBox.Show(text);
            }
        }

        public void DustCollector_LowerPos_Comm_Init()
        {
            string m_strPortName = "COM6";
            int m_nBaudRate = 115200;
            int m_nDataBits = 8;
            StopBits m_stopBits = StopBits.One;
            Parity m_parity = Parity.None;
            Handshake m_handshake = Handshake.None;

            //  Comm. Port 설정
            m_strPortName = string.Format("COM{0}", Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Serial_CommPort + 1);

            //  Baud Rate 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Serial_CommBaudRate)
            {
                case 0: m_nBaudRate = 1200; break;
                case 1: m_nBaudRate = 2400; break;
                case 2: m_nBaudRate = 4800; break;
                case 3: m_nBaudRate = 9600; break;
                case 4: m_nBaudRate = 19200; break;
                case 5: m_nBaudRate = 38400; break;
                case 6: m_nBaudRate = 57600; break;
                case 7: m_nBaudRate = 115200; break;
                default: m_nBaudRate = 9600; break;
            }

            //  Data Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Serial_CommDataBits)
            {
                case 0: m_nDataBits = 5; break;
                case 1: m_nDataBits = 6; break;
                case 2: m_nDataBits = 7; break;
                case 3: m_nDataBits = 8; break;
                default: m_nDataBits = 8; break;
            }

            //  Stop Bits 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Serial_CommStopBits)
            {
                case 0: m_stopBits = StopBits.One; break;
                case 1: m_stopBits = StopBits.OnePointFive; break;
                case 2: m_stopBits = StopBits.Two; break;
                default: m_stopBits = StopBits.One; break;
            }

            //  Parity 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Serial_CommParity)
            {
                case 0: m_parity = Parity.None; break;
                case 1: m_parity = Parity.Odd; break;
                case 2: m_parity = Parity.Even; break;
                default: m_parity = Parity.None; break;
            }

            //  Flow Control 설정
            switch (Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Serial_CommFlowControl)
            {
                case 0: m_handshake = Handshake.None; break;
                case 1: m_handshake = Handshake.XOnXOff; break;
                case 2: m_handshake = Handshake.RequestToSend; break;
                case 3: m_handshake = Handshake.RequestToSendXOnXOff; break;
                default: m_handshake = Handshake.None; break;
            }

            if (!Equipment.stCommunicationSet[(int)Equipment.CommList.DustCollector_Lower].Connect)
                return;

            m_dustCollector_LowerPos_Comm = new SerialCommDustCollector2Port();
            m_dustCollector_LowerPos_Comm.DataReceivedHandler = DustCollector_LowerPos_DataReceivedHandler;
            m_dustCollector_LowerPos_Comm.DisconnectedHandler = DustCollector_LowerPos_DisconnectedHandler;
            if (!m_dustCollector_LowerPos_Comm.OpenComm(m_strPortName, m_nBaudRate, m_nDataBits, m_stopBits, m_parity, m_handshake))
            {
                string text = string.Format("{0} Port Open Failed! (Dust Collector, Lower Pos.)", m_strPortName);
                MessageBox.Show(text);
            }
        }

