                    m_bRet = false;
                }
            }
            else if (m_nDustCollector == (int)nDustCollector.DustCollector_Lower)
            {
                if (m_dustCollector_LowerPos_Comm != null)
                {
                    if (m_dustCollector_LowerPos_Comm.IsOpen)
