                        DustCollectorComm_Send_Write((int)WorkStage.nDustCollector.DustCollector_Lower, m_strAddress, 1, m_strData);

                        m_bRet = true;
                    }
                }
                else
                {
                    m_bRet = false;
                }
            }

            return m_bRet;
        }

