                m_cSendCmd[3] = (byte)'R';
                m_cSendCmd[4] = (byte)'T';
                m_cSendCmd[5] = chrCR;
                m_cSendCmd[6] = chrLF;
            }
            else
            {
                m_cSendCmd = new byte[6];            //  6 : 'STOP' + CR + LF

                m_cSendCmd[0] = (byte)'S';
                m_cSendCmd[1] = (byte)'T';
                m_cSendCmd[2] = (byte)'O';
                m_cSendCmd[3] = (byte)'P';
                m_cSendCmd[4] = chrCR;
                m_cSendCmd[5] = chrLF;
