                m_bRapidLxLaser_LaserStart = m_bStart;              //  System Status 문구 변경을 위한 변수

                m_bRet = true;
            }

            return m_bRet;
        }

        public bool RapidLxLaserComm_Laser_SystemFaults_Read()
        {
            bool m_bRet = false;

            string m_strSendData = "";
            byte[] m_cSendCmd = null;

            m_cSendCmd = new byte[4];            //  4 : '?F' + CR + LF

            m_cSendCmd[0] = (byte)'?';
            m_cSendCmd[1] = (byte)'F';
