        {
            //  측정 모드로 변경
            //  R0\r

            bool m_bRet = false;

            string m_strSendData = "";
            byte[] m_cSendCmd = null;

            m_cSendCmd = new byte[3];

            m_cSendCmd[0] = (byte)'R';
            m_cSendCmd[1] = (byte)'0';
            m_cSendCmd[2] = chrCR;

            if (m_SocketLaserHeightSensor.isConnected)
            {
