        private async void Timer_MainWork_Tick(object sender, ElapsedEventArgs e)
        {
            // 중복 실행 방지
            if (_isMainWorkRunning)
            {
                //Console.WriteLine("Scanner Calibration is already running. Skipping this call.");
                return;
            }

            try
            {
                _isMainWorkRunning = true;

                //  타워램프 상태 갱신
                //  Alarm 상태
                if (AlarmManager.Instance.IsAlarm)
                {
                    if (CommonModule.Instance.TowerLamp.Is_Green_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Green_Off();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Yellow_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Yellow_Off();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Red_On() == 0)
                    {
                        CommonModule.Instance.TowerLamp.Red_On();
                    }

                    if (CommonModule.Instance.TowerLamp_BuzzerStop)
                    {
                        if (CommonModule.Instance.TowerLamp.Is_Buzzer_On() != 0)
                        {
                            CommonModule.Instance.TowerLamp.Buzzer_Off();
                        }
                    }
                    else
                    {
                        if (CommonModule.Instance.TowerLamp.Is_Buzzer_On() == 0)
                        {
                            CommonModule.Instance.TowerLamp.Buzzer_On();
                        }
                    }

                    //  버튼 색깔 변경
                    CommonModule.Instance.OperationButtons.StartLamp(false);
                    CommonModule.Instance.OperationButtons.StopLamp(true);
                    CommonModule.Instance.OperationButtons.ResetLamp(false);
                }
                //  자동운전
                else if (Equipment.AutoRunStatus)
                {
                    if (CommonModule.Instance.TowerLamp.Is_Green_On() == 0)
                    {
                        CommonModule.Instance.TowerLamp.Green_On();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Yellow_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Yellow_Off();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Red_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Red_Off();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Buzzer_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Buzzer_Off();
                    }

                    //  버튼 색깔 변경
                    CommonModule.Instance.OperationButtons.StartLamp(true);
                    CommonModule.Instance.OperationButtons.StopLamp(false);
                    CommonModule.Instance.OperationButtons.ResetLamp(false);

                    CommonModule.Instance.TowerLamp_BuzzerStop = false;
                }
                //  Stop
                else
                {
                    if (CommonModule.Instance.TowerLamp.Is_Green_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Green_Off();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Yellow_On() == 0)
                    {
                        CommonModule.Instance.TowerLamp.Yellow_On();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Red_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Red_Off();
                    }
                    if (CommonModule.Instance.TowerLamp.Is_Buzzer_On() != 0)
                    {
                        CommonModule.Instance.TowerLamp.Buzzer_Off();
                    }

                    //  버튼 색깔 변경
                    CommonModule.Instance.OperationButtons.StartLamp(false);
                    CommonModule.Instance.OperationButtons.StopLamp(true);
                    CommonModule.Instance.OperationButtons.ResetLamp(false);

                    CommonModule.Instance.TowerLamp_BuzzerStop = false;
                }


                // Scanner signal로 레이저 발진 유/무 확인.
                UpdateLaserStatus();

                // Scanner Calibration이 활성화되지 않은 경우 종료??
                if (!m_MainWork_Start)
                {
                    return;
                }

                //  Auto Run 모드일 때 칠러가 동작하지 않으면 알람
                if (Equipment.AutoRunStatus)
                {
                    //  Chiller 상태 체크
                    if (!workStageParameter.DI_Chiller_Alarm_Check())
                    {
                        AlarmPost(AlarmKey.Chiller_Alarm);
                        return;
                    }

                    if (!workStageParameter.DI_Chiller_Run())
                    {
                        AlarmPost(AlarmKey.Chiller_Stop);
                        return;
                    }
                }

                //  Loader 에서 WorkStage 로 모듈을 Loading 할 때, Loading 시작과 동시에 가공 데이터 Parsing 하기 위함
                if (Equipment.ProcessingData_Parsing_byLoader)
                {
                    Equipment.ProcessingData_Parsing_byLoader = false;

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Main Tick, Loader Transfer 의 Loading 중 Flag 에 의한 가공 데이터 Parsing 시도");

                    if (!m_bMainWorkCycle_DryRun)
                    {
                        Import_DrawingFile(Equipment.RecipeOpen_DrawingFilePath);

                        if (GetDrillingData() == (int)WorkStage.nGetDataResult.GETDATA_SUCCESS)
                        {
                            Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Main Tick, Loader Transfer, WorkStage 로 Loading 중 가공 데이터 Parsing 성공");

                            //  최초 Data Parsing 후 해당 가공 데이터에 대한 상태 데이터를 초기화 한다. (가공중인 소켓 번호, 소켓 OK NG 여부 등)
                            GlobalSocketStatus_Init();

                            //  Thruhole 가공 Pass 여부를 결정하는 Flag 변수 선언을 여기에서 한번만 한다.
                            GetDrillingData_ProcessingFlagCheck();


                            if (m_stDividedRegion_GroupData != null)
                            {
                                //  메인 화면에 가공위치 표시용
                                Main_SocketPositions = new List<PointD>();

                                for (int i = 0; i < m_stDividedRegion_GroupData[0].nGroup_Num; i++)
                                {
                                    Main_SocketPositions.Add(new PointD(m_stDividedRegion_GroupData[i].dGroupCenter.X, m_stDividedRegion_GroupData[i].dGroupCenter.Y));
                                }

                                if (Main_SocketPositions.Count > 0)
                                {
                                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "가공 소켓 배열 개수 계산을 위한 소켓 데이터 있음.");

                                    //  메인 화면에 그려지는 가공위치의 개수
                                    (Main_SocketPositions_RowCount, Main_SocketPositions_ColumnCount) = CalculateArraySize(Main_SocketPositions);

                                    //  가공 소켓이 몇개의 영역으로 나눠지는지
                                    Main_SocketPositions_SubRowCount = m_stDividedRegion_GroupData[0].nGroup_Region_Divided_Y > 0 ? m_stDividedRegion_GroupData[0].nGroup_Region_Divided_Y : 1;
                                    Main_SocketPositions_SubColumnCount = m_stDividedRegion_GroupData[0].nGroup_Region_Divided_X > 0 ? m_stDividedRegion_GroupData[0].nGroup_Region_Divided_X : 1;

                                    Main_SocketPositions_Draw = true;
                                }
                                else
                                {
                                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "가공 소켓 배열 개수 계산을 위한 소켓 데이터 없음. (Data Parsing 이 정상적으로 이루어졌으면 여기 들어오면 안됨)");
                                }
                            }
                        }
                        else
                        {
                            Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Main Tick, Loader Transfer, WorkStage 로 Loading 중 가공 데이터 Parsing 실패");
                        }
                    }
                }


                // 단계별 실행
                Run_MainWork_Cycle_Func();
            }
            catch (Exception ex)
            {
                Log.Write(ex);
                Console.WriteLine($"Error in Timer_Main Work_Elapsed: {ex.Message}");
            }
            finally
            {
                _isMainWorkRunning = false; // 플래그 해제
            }
        }

        private void Timer_MainWork_Func(object sender, EventArgs e)
        {
            //  동시에 진행되지 않는 함수들만 동일한 타이머로 한다.

            m_btimer_MainWork_Stop = false;
            timer_MainWork.Enabled = false;

            //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            //  메인 화면 갱신용 변수
            Equipment.m_bMainProcessStatus_WorkStage_Module_Process_Complete = m_bMainWorkCycle_Complete;
            //  메인 화면 갱신용 변수
            //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

            Run_MainWork_Cycle_Func();

            if (!m_btimer_MainWork_Stop)
            {
                timer_MainWork.Enabled = true;
            }
        }
        public void SetRecoveryLaserDrilling_MainStep(int LaserDrilling_MainStep)
        {
            if (LaserDrilling_MainStep < (int)LaserDrilling_Step.Start)
            {
                m_nLaserDrilling_MainStep_Recovery = (int)LaserDrilling_MainStep;
            }
            else if (LaserDrilling_MainStep <= (int)LaserDrilling_Step.StageZ_MoveProcessingPos_DoneCheck)
            {
                m_nLaserDrilling_MainStep_Recovery = (int)LaserDrilling_Step.Start;
            }
            else if (LaserDrilling_MainStep <= (int)LaserDrilling_Step.DrillingData_LayerRemainedCheck)
            {
                m_nLaserDrilling_MainStep_Recovery = (int)LaserDrilling_Step.DrillingData_Load;
            }
            else if (LaserDrilling_MainStep < (int)LaserDrilling_Step.ThruHole_DrillingWork_Start)
            {
                m_nLaserDrilling_MainStep_Recovery = LaserDrilling_MainStep;
            }
            else if (LaserDrilling_MainStep <= (int)LaserDrilling_Step.ThruHole_StageZ_MoveStartPos_DoneCheck)
            {
                m_nLaserDrilling_MainStep_Recovery = (int)LaserDrilling_Step.ThruHole_StageZ_MoveStartPos;
            }
            else if (LaserDrilling_MainStep <= (int)LaserDrilling_Step.ThruHole_LayerParameter_LaserPower_Change_DoneCheck)
            {
                m_nLaserDrilling_MainStep_Recovery = (int)LaserDrilling_Step.ThruHole_LayerParameter_LaserPower_Change;
            }
            else if (LaserDrilling_MainStep <= (int)LaserDrilling_Step.ThruHole_LayerParameter_ZOffset_Move_DoneCheck)
