        public double GetDriveSpace(string m_strDrive)
        {
            double m_dSpace = 0.0;

            DriveInfo drv = new DriveInfo(m_strDrive);
            m_dSpace = (double)drv.TotalFreeSpace / 1024.0 / 1024.0 / 1024.0;

            return m_dSpace;
        }

