        public void MapData_Load()
        {
            string strFileName = "";
            FileInfo fi;

            //Stage_forMap_Scanner = new XyzyStage("Map_Scanner");
            //Stage_forMap_FineCam = new XyzyStage("Map_FineCam");
            //Stage_forMap_CalPos_Scanner = new XyzyStage("Map_CalPos_Scanner");
            //Stage_forMap_CalPos_FineCam = new XyzyStage("Map_CalPos_FineCam");

            if (Equipment.MappingData_FilePath_Stage_Scanner != "")
