                strFileName = Equipment.MappingData_FilePath_Stage_Scanner;
                fi = new FileInfo(strFileName);
                if (fi.Exists)
                {
                    if (interpolator_Scanner == null)
                    {
                        interpolator_Scanner = new PerspectiveProjectionInterpolator();
                    }

                    interpolator_Scanner.Load(strFileName);
                }
            }

            if (Equipment.MappingData_FilePath_Stage_FineCam != "")
            {
                strFileName = Equipment.MappingData_FilePath_Stage_FineCam;
                fi = new FileInfo(strFileName);
                if (fi.Exists)
                {
                    if (interpolator_FineCam == null)
                    {
                        interpolator_FineCam = new PerspectiveProjectionInterpolator();
                    }

                    interpolator_FineCam.Load(strFileName);
                }
            }

            if (Equipment.MappingData_FilePath_StageCal_Scanner != "")
            {
                strFileName = Equipment.MappingData_FilePath_StageCal_Scanner;
                fi = new FileInfo(strFileName);
                if (fi.Exists)
                {
                    if (interpolator_CalPos_Scanner == null)
                    {
                        interpolator_CalPos_Scanner = new PerspectiveProjectionInterpolator();
                    }
                    interpolator_CalPos_Scanner.Load(strFileName);
                }
            }

            if (Equipment.MappingData_FilePath_StageCal_FineCam != "")
            {
                strFileName = Equipment.MappingData_FilePath_StageCal_FineCam;
                fi = new FileInfo(strFileName);
                if (fi.Exists)
                {
                    if (interpolator_CalPos_FineCam == null)
                    {
                        interpolator_CalPos_FineCam = new PerspectiveProjectionInterpolator();
                    }
                    interpolator_CalPos_FineCam.Load(strFileName);
                }
            }
        }


        public void MapData_Apply(int m_nMapDataType)
        {
            switch (m_nMapDataType)
            {
                case (int)nMapData_Type.MapData_Stage_Scanner:
                    if ((Stage != null) && (interpolator_Scanner != null))
                    {
                        Stage.Interpolator = interpolator_Scanner;
                    }
                    break;


                case (int)nMapData_Type.MapData_Stage_FineCam:
                    if ((Stage != null) && (interpolator_FineCam != null))
                    {
                        Stage.Interpolator = interpolator_FineCam;
                    }

                    break;


                case (int)nMapData_Type.MapData_Stage_CalPos_Scanner:
                    if ((Stage != null) && (interpolator_CalPos_Scanner != null))
                    {
                        Stage.Interpolator = interpolator_CalPos_Scanner;
                    }

                    break;


                case (int)nMapData_Type.MapData_Stage_CalPos_FineCam:
                    if ((Stage != null) && (interpolator_CalPos_FineCam != null))
                    {
                        Stage.Interpolator = interpolator_CalPos_FineCam;
                    }

                    break;
            }
        }

