        //  원점 기준 회전
        public static PointD RotatePoint(PointD cen, PointD p1, double radian)
        {
            PointD rP = p1;

            //  CCW 회전
            rP.X = ((p1.X - cen.X) * Math.Cos(radian) - (p1.Y - cen.Y) * Math.Sin(radian)) + cen.X;
            rP.Y = ((p1.X - cen.X) * Math.Sin(radian) + (p1.Y - cen.Y) * Math.Cos(radian)) + cen.Y;

            //  CW 회전
            //rP.X = ((p1.X - cen.X) * Math.Cos(radian) + (p1.Y - cen.Y) * Math.Sin(radian)) + cen.X;
            //rP.Y = (-(p1.X - cen.X) * Math.Sin(radian) + (p1.Y - cen.Y) * Math.Cos(radian)) + cen.Y;

            return rP;
        }

        //  제자리 회전
        public static PointD RotatePoint_CurPos(PointD cen, PointD p1, double radian)
        {
            //  현재 Group Center 좌표
            PointD curCenter = cen;

            PointD rP = p1;
            p1.X -= curCenter.X;
            p1.Y -= curCenter.Y;

            p1.X -= curCenter.X;
            p1.Y -= curCenter.Y;

            //  CCW 회전
            rP.X = ((p1.X) * Math.Cos(radian) - (p1.Y) * Math.Sin(radian));
            rP.Y = ((p1.X) * Math.Sin(radian) + (p1.Y) * Math.Cos(radian));

            //  CW 회전
            //rP.X = ((p1.X) * Math.Cos(radian) + (p1.Y) * Math.Sin(radian));
            //rP.Y = (-(p1.X) * Math.Sin(radian) + (p1.Y) * Math.Cos(radian));

            rP.X += curCenter.X;
            rP.Y += curCenter.Y;

            return rP;
        }


        #region Align Mark Find

        //PreAlign -
        void Run_FindAlignMark_Func()
        {
            switch (m_nFindAlignMark_Step)
            {
                case (int)FindAlignMark_Step.Start:
                    //On_LogFile_Add(LOG_OPERATION, "홈 실행 루틴, 시작.");
                    //Display_Event("홈 실행 루틴 : 시작.");

                    Log.Write("SLD-200", Equipment.User_Name, "Pre Align Mark", "마크 찾기 시작");
                    Equipment.MachineStop_byAlarm = false;
                    m_bFindAlignMark_OK = false;
                    m_bFindUpperAlignMark_OK = false;
                    m_bFindLowerAlignMark_OK = false;
                    m_bFindAlignMark_Complete = false;
                    m_nVisionAligner_Type = (int)Aligner_Type.Aligner_PreAlign_Lower;

                    //  라이브 상태가 아니면 라이브로 변경
                    if (jigAligner_LowRes.Camera.IsLiveOn == false)
                    {
                        //jigAligner_LowRes.Camera.StartLive();
                    }

                    //  어느 쪽 마크를 찾을 것인지... 1번 마크인지 2번 마크인지...
                    m_nFindAlignMarkType = 0; //무조건 2개 다 찾어.
                    if ((m_nFindAlignMarkType == (int)AlignMarkType.ALIGN_2POINT) || (m_nFindAlignMarkType == (int)AlignMarkType.ALIGN_1STMARK))        //  2 Point 찾기나, 1번 마크 찾기일 경우
                    {
                        m_nFindAlignMarkType = (int)AlignMarkType.ALIGN_1STMARK;
                    }
                    else                                                                                                                                //  위 경우가 아니면 2번 마크 찾는 것으로...
                    {
                        m_nFindAlignMarkType = (int)AlignMarkType.ALIGN_2NDMARK;
                    }

                    m_nFindAlignMark_Step = (int)FindAlignMark_Step.FindMark_Start;
                    break;


                case (int)FindAlignMark_Step.FindMark_Start:                                           //  Align Start
                    //if (!m_bLowerVision_Align)
                    m_nVisionAligner_Type = 7;
                    if (m_nVisionAligner_Type == (int)Aligner_Type.Aligner_PreAlign_Lower)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Pre Align Mark", "Rows 카메라 Circle 마크 찾기 시작");
                        //  라이브 상태가 아니면 라이브로 변경
                        if (jigAligner_LowRes.Camera.IsLiveOn == false)
                        {
                            jigAligner_LowRes.Camera.StopLive();
                        }

                        try
                        {
                            //Todo: PreAlign 확인!!!
                            //Recipe Data 전달하기!

                            if(stVisionRecipeSet.ePreAlgorithmType == VisionAlgorithmType.PatternMatching)
                            {
                                jigAligner_LowRes.Recipe.PatternMatchingParameter = stVisionRecipeSet.PrePatternMatching;
                                jigAligner_LowRes.Recipe.InspectRoiStartLocation = stVisionRecipeSet.pointPreInspectRoiStartLocation;
                                jigAligner_LowRes.Recipe.InspectRoiEndLocation = stVisionRecipeSet.pointPreInspectRoiEndLocation;
                                jigAligner_LowRes.Recipe.TrainRoiStartLocation = stVisionRecipeSet.pointPreTrainRoiStartLocation;
                                jigAligner_LowRes.Recipe.TrainRoiEndLocation = stVisionRecipeSet.pointPreTrainRoiEndLocation;
                                jigAligner_LowRes.Work();
                            }
                            else if(stVisionRecipeSet.ePreAlgorithmType == VisionAlgorithmType.CircleDetection)
                            {
                                jigAligner_LowRes.Work();
                            }
                            else
                            {
                                jigAligner_LowRes.Recipe.PatternMatchingParameter = stVisionRecipeSet.PrePatternMatching;
                                jigAligner_LowRes.Recipe.InspectRoiStartLocation = stVisionRecipeSet.pointPreInspectRoiStartLocation;
                                jigAligner_LowRes.Recipe.InspectRoiEndLocation = stVisionRecipeSet.pointPreInspectRoiEndLocation;
                                jigAligner_LowRes.Recipe.TrainRoiStartLocation = stVisionRecipeSet.pointPreTrainRoiStartLocation;
                                jigAligner_LowRes.Recipe.TrainRoiEndLocation = stVisionRecipeSet.pointPreTrainRoiEndLocation;
                                jigAligner_LowRes.Work();
                            }

                                Log.Write("SLD-200", Equipment.User_Name, "Find Align Mark", "Work() 완료");
                        }
                        catch(Exception ex)
                        {
                            Log.Write(ex);
                        }
                    }
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Pre Align Mark", "지정되지 않은 얼라이너");

                        m_bFindLowerAlignMark_OK = false;
                    }

                    m_nFindAlignMark_Step = (int)FindAlignMark_Step.FindMark_ResultCheck;

                    break;


                case (int)FindAlignMark_Step.FindMark_ResultCheck:                                        //  Align 결과 확인

                    m_nFindAlignMark_Step = (int)FindAlignMark_Step.Complete;
                    break;


                case (int)FindAlignMark_Step.Complete:

                    Log.Write("SLD-200", Equipment.User_Name, "Find Align Mark", "마크 찾기 완료");

                    if (m_nVisionAligner_Type == (int)Aligner_Type.Aligner_PreAlign_Lower)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Pre Align Mark", "카메라 circle 마크 찾기 완료");

                        if ((jigAligner_LowRes.FirstPosition.X == 0.0) || (jigAligner_LowRes.FirstPosition.Y == 0.0))
                        {
                            m_bFindLowerAlignMark_OK = false;
                        }
                        else
                        {
                            m_bFindLowerAlignMark_OK = true;
                        }
                    }
                    m_bFindAlignMark_Complete = true;
                    m_nFindAlignMark_Step = (int)FindAlignMark_Step.None;
                    break;
            }
        }
        #endregion

        #region Home Function
        //protected bool IsAlarm()
        public bool IsAlarm()
        {
            bool bResult = false;
            try
            {
                var v = AlarmManager.Instance.Alarms;
                var alarmList = v.Where(t => t.Code >= (int)AlarmKey.FirstAlarm && t.Code <= (int)AlarmKey.LastAlarm);
                return alarmList.Any();
            }
            catch (Exception ex)
            {
                Log.Write(ex);
            }
            return bResult;
        }
