            switch (m_nHomeStep)
            {
                case (int)Home_Step.Start:
                    Log.Write("SLD-200", Equipment.User_Name, "Machine Initialize", "시작");

                    Equipment.MachineStop_byAlarm = false;

                    m_nHomeAxisCount = 0;
