                    //  Glass Cleaning 중이거나
                    //  Cal Sheet Change 중이거나
                    //  등등등이면 이동 안되도록 해야 한다.

                    //else if (unloader.m_nUnloader_Transfer_Step > (int)Unloader.Unloader_Transfer_Step.None)
                    //{
                    //    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "UL Transfer 가 동작중이므로 Stage 이동 중지.");

                    //    //  Out.
                    //    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;
                    //}
                    else
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage, Fine Camera Center 위치 이동 조건 OK");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos;
                    }
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos:                            //  Scanner Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                    //  Target Position 변경 : Z 축 대기 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_ScannerZ_Move_ReadyPos_DoneCheck:                       //  Scanner Z 축, 대기 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 완료 확인");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos:                            //  Stage XY 축, Fine Camera Center 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Fine Camera Center 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("High_Mag_Camera_Center");

                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                    //  맵 데이터 변경 (기준위치 : Scanner)
                    //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                    //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                    MapData_Apply((int)WorkStage.nMapData_Type.MapData_Stage_FineCam);
                    //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

                    //  Target Position 변경 : Module Unloading 위치
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_HighMagCamPos].Stage_X;
                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_HighMagCamPos].Stage_Y;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                    xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_STAGE_MOVE);

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos_DoneCheck;
                    break;


                case (int)WorkStage_Move_Step.ToCameraCenterPos_StageXY_Move_StageCameraCenterPos_DoneCheck:                       //  Stage XY 축, Camera Center 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Fine Camera Center 위치로 이동 완료");

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.Complete;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_STAGE_MOVE) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage XY 축, Fine Camera Center 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_MainWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                        MessageBox.Show("Stage XY 축, Fine Camera Center 위치로 이동 실패.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;
                /// <summary>
                /// Stage and Camera Center Pos Move - 완료
                /// </summary>

                case (int)WorkStage_Move_Step.Complete:

                    Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "완료");

                    //  m_bHomeOK = true;

                    //timer_Motion_Home.Enabled = false;
                    //m_btimer_Motion_Home_Stop = true;

                    switch (m_nWorkStageMoveType)
                    {
                        case (int)WorkStageMoveType.MoveTo_LoadingPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Loading 위치로 이동 완료");                                        //  요거 하고
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_LoadingZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_UnloadingPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Unloading 위치로 이동 완료");                                      //  요거 하고
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_UnloadingZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_GlassCleaningPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Scanner 렌즈 보호 유리를 청소하기 위한 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_CalSheetChangePos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Calibration Acryl 교체 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_ScannerCenterPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Scanner Center 위치로 이동 완료");                                 //  요거 하고     
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_WorkingZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_CameraCenterPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Fine Camera 위치로 이동 완료");                                    //  요거 하고   
                            m_nWorkStagePosition = (int)WorkStage.WorkStagePosition.WorkStage_FineCameraZone;
                            break;

                        case (int)WorkStageMoveType.MoveTo_CameraReticleGlassPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Fine Camera 가 Reticle Glass 를 확인하는 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_PowerCheckPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Stage 의 Power Meter 측정 위치로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_FrontPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage 를 앞쪽으로 이동 완료");
                            break;

                        case (int)WorkStageMoveType.MoveTo_RearPos:
                            Log.Write("SLD-200", Equipment.User_Name, "Work Stage Move Cycle", "Work Stage 를 장비 뒤쪽으로 이동 완료");
                            break;
                    }

                    m_nWorkStage_Move_Step = (int)WorkStage_Move_Step.None;

                    //MessageBox.Show(m_strTemp, "Information!", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    break;
            }
        }

        #endregion



