        #region Power Meter Comm Function

        void Run_PowerMeterBDSComm_Func()
        {
            switch (m_nPowerMeterBDSCommStep)
            {
                case (int)PowerMeterBDSComm_Step.Start:
                    m_bLaserPowerMeter_ExitPos_CommData_Received = false;
                    m_strLaserPowerMeter_ExitPos_Comm_ReceivedData = "";

                    m_nPowerMeterBDSCommRecvData_CR_Count = 0;
                    m_strPowerMeterBDS_PowerValue = "";
                    m_strPowerMeterBDS_DataStatus = "";

                    m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Get;
                    break;


                case (int)PowerMeterBDSComm_Step.PM_Value_Get:                        //  읽기 (Source Pos.)
                    //  Source 측 PowerMeter 값 읽기

                    m_bLaserPowerMeter_ExitPos_CommData_Received = false;
                    m_strLaserPowerMeter_ExitPos_Comm_ReceivedData = "";
                    m_nPowerMeterBDSCommRecvData_CR_Count = 0;

                    if (LaserPowerMeter_GetValue((int)nPowerMeter.ExitPos))
                    {
                        TickCount_Start((int)TickType.TICK_POWERMETER_COMM_BDS);

                        m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Received;
                    }
                    else
                    {
                        m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.None;

                        MessageBox.Show("Laser PowerMeter-1 Comm. Failed.", "Error");
                    }
                    break;


                case (int)PowerMeterBDSComm_Step.PM_Value_Received:
                    if (m_bLaserPowerMeter_ExitPos_CommData_Received)
                    {
                        //  데이터 체크 (chrCR 이 2개인지 확인)
                        for (int i = 0; i < m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Length; i++)
                        {
                            if (m_strLaserPowerMeter_ExitPos_Comm_ReceivedData[i] == chrCR)
                                m_nPowerMeterBDSCommRecvData_CR_Count++;
                        }

                        if (m_nPowerMeterBDSCommRecvData_CR_Count == 2)         //  수신 데이터 안에 \r 이 2개이면? 정상 데이터.
                        {
                            string[] words = m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Split((char)chrCR);

                            if (words.Length < 2)
                            {
                                m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Get;
                            }
                            else
                            {
                                m_strPowerMeterBDS_PowerValue = words[0].Trim();
                                m_strPowerMeterBDS_DataStatus = words[1].Trim();

                                if (m_strPowerMeterBDS_DataStatus == "OK")
                                {
                                    try
                                    {
                                        m_dPowerMeterBDS_Value = Equipment.ToDouble(m_strPowerMeterBDS_PowerValue);
                                    }
                                    catch (Exception ex)
                                    {
                                        Log.Write(ex);
                                        Log.Write("SLD-200", Equipment.User_Name, "Power Meter BDS Comm", "Convert Error : " + ex.Message);
                                        m_dPowerMeterBDS_Value = 0.0;
                                    }
                                }
                                else
                                {
                                    m_dPowerMeterBDS_Value = 0.0;
                                }

                                m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Get;
                            }
                        }
                        else if (m_nPowerMeterBDSCommRecvData_CR_Count == 1)         //  수신 데이터 안에 \r 이 1개이면? 정상 데이터.
                        {
                            string[] words = m_strLaserPowerMeter_ExitPos_Comm_ReceivedData.Split((char)chrCR);

                            m_strPowerMeterBDS_PowerValue = words[0].Trim();
                            //m_strPowerMeter_DataStatus = words[1].Trim();

                            //if (m_strPowerMeter_DataStatus == "OK")
                            //{

                            if (m_strPowerMeterBDS_PowerValue.Length > 0)
                            {
                                try
                                {
                                    m_dPowerMeterBDS_Value = Equipment.ToDouble(m_strPowerMeterBDS_PowerValue);
                                }
                                catch (Exception ex)
                                {
                                    Log.Write(ex);
                                    Log.Write("SLD-200", Equipment.User_Name, "Power Meter BDS Comm", "Convert Error : " + ex.Message);
                                    m_dPowerMeterBDS_Value = 0.0;
                                }
                            }
                            //}
                            //else
                            //{
                            //    m_dPowerMeter_ExitPos_Value = 0.0;
                            //}

                            m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Get;
                        }
                        else                                            //  수신 데이터 안에 \r 이 2개가 아니면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Get;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_POWERMETER_COMM_BDS) >= 500)
                    {
                        m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.PM_Value_Get;
                    }
                    break;


                case (int)PowerMeterBDSComm_Step.Complete:
                    //timer_Calibration.Enabled = false;
                    m_nPowerMeterBDSCommStep = (int)PowerMeterBDSComm_Step.None;
                    break;
            }
        }

