        #region Electro Pnuematic Regulator Comm Func

        void Run_EPROComm_Func()
        {
            string m_strData = "";

            //if ((m_nLaserDrilling_MainStep != (int)LaserDrilling_Step.None) ||

            //    ((m_nLaserPowerCal_Step >= (int)LaserPowerCal_Step.ThruHole_LaserParameter_Change_Start) && (m_nLaserPowerCal_Step <= (int)LaserPowerCal_Step.ThruHole_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_Step >= (int)LaserPowerCal_Step.OutLine_LaserParameter_Change_Start) && (m_nLaserPowerCal_Step <= (int)LaserPowerCal_Step.OutLine_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_Step >= (int)LaserPowerCal_Step.Drilling_LaserParameter_Change_Start) && (m_nLaserPowerCal_Step <= (int)LaserPowerCal_Step.Drilling_LaserParameter_Change_Complete)) ||

            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Thruhole_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Thruhole_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Outline_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Outline_LaserParameter_Change_Complete)) ||
            //    ((m_nLaserPowerCal_byRange_Step >= (int)LaserPowerCal_byRange_Step.Drilling_LaserParameter_Change_Start) && (m_nLaserPowerCal_byRange_Step <= (int)LaserPowerCal_byRange_Step.Drilling_LaserParameter_Change_Complete)))
            //{
            //    if (m_nLaserCommStep == (int)LaserComm_Step.GateStatus_Check)
            //    {
            //        m_bLaserComm_Paused = true;
            //        return;
            //    }
            //    else
            //    {
            //        m_bLaserComm_Paused = false;
            //    }
            //}
            //else
            //{
            //    m_bLaserComm_Paused = false;
            //}


            if (m_electroRegulator_Comm == null)
            {
                m_nEPROCommStep = (int)EPROComm_Step.None;
                return; ;
            }

            if (!m_electroRegulator_Comm.IsOpen)
            {
                m_nEPROCommStep = (int)EPROComm_Step.None;
                return;
            }

            switch (m_nEPROCommStep)
            {
                case (int)EPROComm_Step.Start:

                    m_nEPROCommRecvData_LF_Count = 0;              //  수신된 데이터 안에 chrLF 가 1개만 존재하는지 확인
                    m_dEPRO_Value = 0.0;
                    m_dEPRO_SetValue = 0.0;

                    m_nEPROCommStep = (int)EPROComm_Step.Comm_Pause_Check;
                    break;


                case (int)EPROComm_Step.Comm_Pause_Check:


                    m_nEPROCommStep = (int)EPROComm_Step.EPROComm_Read;
                    break;


                case (int)EPROComm_Step.EPROComm_Read:
                    //  읽기

                    if (m_electroRegulator_Comm.IsOpen)
                    {
                        m_bElectroRegulator_CommData_Received = false;
                        m_strElectroRegulator_Comm_ReceivedData = "";
                        m_nEPROCommRecvData_LF_Count = 0;

                        ElectroPneumaticRegulatorComm_Pressure_Read();

                        TickCount_Start((int)TickType.TICK_EPRO_COMM);

                        m_nEPROCommStep = (int)EPROComm_Step.EPROComm_Received;
                    }
                    else
                    {
                        m_nEPROCommStep = (int)EPROComm_Step.None;

                        MessageBox.Show("EPRO Comm. Not Opened.", "Error");
                    }
                    break;


                case (int)EPROComm_Step.EPROComm_Received:
                    if (m_bElectroRegulator_CommData_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
                        for (int i = 0; i < m_strElectroRegulator_Comm_ReceivedData.Length; i++)
                        {
                            if (m_strElectroRegulator_Comm_ReceivedData[i] == chrLF)
                                m_nEPROCommRecvData_LF_Count++;
                        }

                        if (m_nEPROCommRecvData_LF_Count == 1)         //  수신 데이터 안에 \n 이 1개이면? 정상 데이터.
                        {
                            m_strData = m_strElectroRegulator_Comm_ReceivedData.Substring(0, m_strElectroRegulator_Comm_ReceivedData.Length - 1);

                            //  읽은 값을 kPa로 변환
                            m_dEPRO_Value = ElectroPneumaticRegulatorComm_ReceivedData_ConvertTo_Pressure(m_strData);

                            m_bElectroRegulator_CommData_Received = false;
                            m_strElectroRegulator_Comm_ReceivedData = "";
                            m_nEPROCommRecvData_LF_Count = 0;

                            m_nEPROCommStep = (int)EPROComm_Step.EPROComm_Read_SetValue;
                        }
                        else                                            //  수신 데이터 안에 \n 이 2개 이상이면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            m_bElectroRegulator_CommData_Received = false;
                            m_strElectroRegulator_Comm_ReceivedData = "";
                            m_nEPROCommRecvData_LF_Count = 0;

                            m_nEPROCommStep = (int)EPROComm_Step.EPROComm_Read;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_EPRO_COMM) >= 500)
                    {
                        m_bElectroRegulator_CommData_Received = false;
                        m_strElectroRegulator_Comm_ReceivedData = "";
                        m_nEPROCommRecvData_LF_Count = 0;

                        m_nEPROCommStep = (int)EPROComm_Step.EPROComm_Read_SetValue;
                    }
                    break;


                case (int)EPROComm_Step.EPROComm_Read_SetValue:
                    //  읽기

                    if (m_electroRegulator_Comm.IsOpen)
                    {
                        m_bElectroRegulator_CommData_Received = false;
                        m_strElectroRegulator_Comm_ReceivedData = "";
                        m_nEPROCommRecvData_LF_Count = 0;

                        ElectroPneumaticRegulatorComm_SettingPressure_Read();

                        TickCount_Start((int)TickType.TICK_EPRO_COMM);

                        m_nEPROCommStep = (int)EPROComm_Step.EPROComm_SetValue_Received;
                    }
                    else
                    {
                        m_nEPROCommStep = (int)EPROComm_Step.None;

                        MessageBox.Show("EPRO Comm. Not Opened.", "Error");
                    }
                    break;


                case (int)EPROComm_Step.EPROComm_SetValue_Received:
                    if (m_bElectroRegulator_CommData_Received)
                    {
                        //  데이터 체크 (2개가 붙어서 들어오는 경우가 있어서... ctrLF 가 1개인지 확인)
                        for (int i = 0; i < m_strElectroRegulator_Comm_ReceivedData.Length; i++)
                        {
                            if (m_strElectroRegulator_Comm_ReceivedData[i] == chrLF)
                                m_nEPROCommRecvData_LF_Count++;
                        }

                        if (m_nEPROCommRecvData_LF_Count == 1)         //  수신 데이터 안에 \n 이 1개이면? 정상 데이터.
                        {
                            m_strData = m_strElectroRegulator_Comm_ReceivedData.Substring(0, m_strElectroRegulator_Comm_ReceivedData.Length - 1);

                            //  읽은 값을 kPa로 변환
                            m_dEPRO_SetValue = ElectroPneumaticRegulatorComm_ReceivedData_ConvertTo_Pressure(m_strData);

                            m_bElectroRegulator_CommData_Received = false;
                            m_strElectroRegulator_Comm_ReceivedData = "";
                            m_nEPROCommRecvData_LF_Count = 0;

                            m_nEPROCommStep = (int)EPROComm_Step.Comm_Pause_Check;
                        }
                        else                                            //  수신 데이터 안에 \n 이 2개 이상이면? 데이터가 잘못 들어온 것으로 판단하여 다시 데이터 읽기.
                        {
                            m_bElectroRegulator_CommData_Received = false;
                            m_strElectroRegulator_Comm_ReceivedData = "";
                            m_nEPROCommRecvData_LF_Count = 0;

                            m_nEPROCommStep = (int)EPROComm_Step.EPROComm_Read_SetValue;
                        }
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_EPRO_COMM) >= 500)
                    {
                        m_bElectroRegulator_CommData_Received = false;
                        m_strElectroRegulator_Comm_ReceivedData = "";
                        m_nEPROCommRecvData_LF_Count = 0;

                        m_nEPROCommStep = (int)EPROComm_Step.Comm_Pause_Check;
                    }
                    break;
            }
        }

