        #region Dry Run Cycle Function

        private void Func_DryRun_Cycle()
        {
            bool success = true;
            string m_strTemp = "";

            double lfVelocity = 0.0f;
            double lfAccDec = 0.0f;


            switch (m_nDryRun_Step)
            {
                case (int)DryRun_Step.Start:
                    Log.Write("SLD-200", "Auto Run", "DryRun 시작");

                    m_bDryRun_Complete = false;

                    m_nDryRun_Step = (int)DryRun_Step.StageZ_MoveReadyPos;
                    break;


                case (int)DryRun_Step.StageZ_MoveReadyPos:                                      //  Z 축, 대기 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치로 이동 시작");

                    //  속도 설정 (스트로크 짧은 Z축은 느리게)
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z,
                                          lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_MAIN);

                    m_nDryRun_Step = (int)DryRun_Step.StageZ_MoveReadyPos_DoneCheck;
                    break;


                case (int)DryRun_Step.StageZ_MoveReadyPos_DoneCheck:                            //  Z 축, 대기 위치로 이동 완료 체크

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Vision_SafetyPos].Vision_Z))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치로 이동 완료 확인");

                        m_nDryRun_Step = (int)DryRun_Step.StageXY_MoveCenterPos;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, 대기 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_LaserDrillingWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nDryRun_Step = (int)DryRun_Step.None;

                        MessageBox.Show("Stage Z 축, 대기 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)DryRun_Step.StageXY_MoveCenterPos:                              //  XY 축, Stage Center 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Stage Center 위치로 이동 시작");

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    xyInterpolatedCoordinate.X = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_X;
                    xyInterpolatedCoordinate.Y = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_Y;
                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_MAIN);

                    m_nDryRun_Step = (int)DryRun_Step.StageXY_MoveCenterPos_DoneCheck;
                    break;


                case (int)DryRun_Step.StageXY_MoveCenterPos_DoneCheck:                 //  XY 축, Stage Center 위치로 이동 완료 체크           

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_X) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_ProcessingPos].Stage_Y))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Stage Center 위치로 이동 완료 확인");

                        m_nDryRun_Step = (int)DryRun_Step.Process_Start;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Stage Center 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_LaserDrillingWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nDryRun_Step = (int)DryRun_Step.None;

                        MessageBox.Show("Stage XY 축, Stage Center 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)DryRun_Step.Process_Start:

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Dry Run, Processing Start");

                    TickCount_Start((int)TickType.TICK_MAIN);

                    m_nDryRun_Step = (int)DryRun_Step.Process_Complete;
                    break;


                case (int)DryRun_Step.Process_Complete:

                    if (TickCount_Elapsed((int)TickType.TICK_MAIN) > (Equipment.DryRun_ProcessingTime * 1000))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Dry Run, Processing Complete");

                        m_nDryRun_Step = (int)DryRun_Step.Complete;
                    }
                    break;


                case (int)DryRun_Step.Complete:

                    m_bDryRun_Complete = true;

                    m_nDryRun_Step = (int)DryRun_Step.None;
                    break;
            }
        }

        #endregion



