        private static void SiriusViewObjectRotateNOffset(double m_dRotCenterX, double m_dRotCenterY, double m_dOffsetX, double m_dOffsetY, double m_dAngle)
        {
            if (Equipment.formMain.InvokeRequired)
            {
                Equipment.formMain.Invoke(new System.Action(() =>
                {
                    SiriusViewObjectRotateNOffset(m_dRotCenterX, m_dRotCenterY, m_dOffsetX, m_dOffsetY, m_dAngle);
                }));
            }
            else
            {
                var Document = Equipment.GetEqpSiriusViewerDocument();
                Document.Action.ActEntityRotate(Document.Action.SelectedEntity, (float)m_dAngle, (float)m_dRotCenterX, (float)m_dRotCenterY);
                Document.Action.ActEntityTransit(Document.Action.SelectedEntity, (float)m_dOffsetX, (float)m_dOffsetY);

            }
        }


        /// <summary>
        /// 회전 이동
        /// </summary>
        /// 
        public PointD[] rotatePolygon(PointD[] m_polygon, PointD m_centroid, double m_angle)
        {
            for (int i = 0; i < m_polygon.Length; i++)
            {
                m_pPolygon_Temp[i] = rotatePoint(m_polygon[i], m_centroid, m_angle);
            }

            return m_pPolygon_Temp;
        }

        public PointD rotatePoint(PointD point, PointD centroid, double radian)
        {
            double x = centroid.X + ((point.X - centroid.X) * Math.Cos(radian) - (point.Y - centroid.Y) * Math.Sin(radian));
            double y = centroid.Y + ((point.X - centroid.X) * Math.Sin(radian) + (point.Y - centroid.Y) * Math.Cos(radian));

            m_pRet.X = x;
            m_pRet.Y = y;

            return m_pRet;
        }


        /// <summary>
        /// Spiral 데이터 생성 (LwPolyline)
        /// </summary>
        /// 
        public LwPolyline SpiralData_Create(double m_dOuterDiameter, double m_dInnerDiameter, double m_nRevolutions, double m_nAngleFactor, double m_dHoleCenter_X, double m_dHoleCenter_Y)
        {

            SpialData sd = SpiralDatas.AddSpialData(new SpialData(m_dOuterDiameter, m_dInnerDiameter, m_nRevolutions, m_nAngleFactor));

            LwPolyline entity = sd.GetLwPolyLineVertices();
            entity.Transit(new Vector2((float)m_dHoleCenter_X, (float)m_dHoleCenter_Y));
            return entity; 
        }

        public bool GlobalSocketStatus_Init()
        {
            bool m_bRet = true;

            // Socket → Layer → Area 기반 초기화
            ProcessManager.Init();
            // Layer 개수 확인
            if (m_stLayerType.m_nLayerCount > 0)
            {
                int layerCount = m_stLayerType.m_nLayerCount;
                int socketCount = m_stDividedRegion_GroupData[0].nGroup_Num;
                int AreaCount = 1;

                int nLayerAddCount = 0;

                int nSocketCount = 0;

                for (int nSocket = 0; nSocket < socketCount; nSocket++)
                {
                    // 소켓 생성 또는 가져오기
                    var socket = ProcessManager.GetSocket(nSocket);

                    for (int i = 0; i < layerCount; i++)
                    {
                        // 레이어 이름 및 번호 설정
                        LayerList m_Layer = (LayerList)m_stLayerType.m_nLayerIndex[i];
                        string layerName = m_Layer.ToString();

                        if (layerName == "Hole1")
                        {
                            // 레이어 추가
                            socket.AddLayer(layerName, nLayerAddCount++);

                            //Area 영역 넣어줘요!! --> ㅇㅋ염
                            // 예시: Area 0~4번 추가 (5개 영역)
                            // 실제 필요한 area 개수가 있다면 해당 로직으로 대체
                            var layer = socket.GetLayer(layerName);
                            for (int area = 0; area < m_stDividedRegion_GroupData[i].m_stDividedRegion_RegionData[0].nRegion_Num; area++)
                            {
                                layer.AddArea(area);
                            }
                        }
                        else if ((layerName == "Thruhole") || (layerName == "Outline") || (layerName == "Marking"))
                        {
                            // 레이어 추가
                            socket.AddLayer(layerName, nLayerAddCount++);

                            //Area 영역 넣어줘요!! --> ㅇㅋ염
                            // 예시: Area 0~4번 추가 (5개 영역)
                            // 실제 필요한 area 개수가 있다면 해당 로직으로 대체
                            var layer = socket.GetLayer(layerName);
                            layer.AddArea(0);
                        }
                    }
                }
            }
            else
            {
                // Parsing된 Layer 데이터 없음
                m_bRet = false;
            }

            //  Layer Info 추가
            //if (m_stLayerType.m_nLayerCount > 0)
            //{
            //    for (int i = 0; i < m_stLayerType.m_nLayerCount; i++)
            //    {
            //        LayerList m_Layer = (LayerList)m_stLayerType.m_nLayerIndex[i];

            //        Layer 추가
            //        ProcessManager.AddLayer(m_Layer.ToString(), i);

            //        for (int nSocket = 0; nSocket < m_stDividedRegion_GroupData[0].nGroup_Num; nSocket++)
            //        {
            //            ProcessManager.GetLayer(i).AddSocket(nSocket);
            //        }
            //    }
            //}
            //else
            //{
            //    Parsing 된 데이터 없음

            //    m_bRet = false;
            //}

            return m_bRet;
        }

        public bool GlobalSocketStatus_Reset()
        {
            bool m_bRet = true;

            //  Layer Info List Reset
            ProcessManager.Reset();

            return m_bRet;
        }

        public bool GlobalSocketStatus_Set(string m_strLayerName, int m_nSocketNumber, int m_nAreaNumber_inSocket, string m_strComment = "")
        {
            bool m_bRet = true;

            // 공정 완료 처리
            //bool result = ProcessManager.MarkAreaProcessed(1, "hole1", 3); // 3: 마지막은 Area 영역 넣어줘야함.
            //시작 index 0 부터 시작.
            //2: 결과값 넣는 곳인데.. 밖에서 넣어줄수있도록 수정 필요
            bool result = ProcessManager.MarkAreaProcessed(m_nSocketNumber, m_strLayerName, m_nAreaNumber_inSocket, 2, m_strComment);

            if (result)
                Console.WriteLine("새로 가공 처리 완료!");
            else
                Console.WriteLine("이미 가공된 영역이거나 처리 실패.");

            //  Socket 상태 세팅
            //ProcessManager.GetLayer(m_strLayerName).SetSocketResult(m_nSocketNumber, m_bSocketResult, m_strComment);

            return m_bRet;
        }

