        // 입력한 좌표와 가까운 4개의 원 좌표와 반지름을 가져오는 메서드
        public FiducialCircle[] GetClosestCircles(PointD inputCoordinate)
        {
            return fiducialCircles
                .OrderBy(c => GetDistance(c.Center, inputCoordinate))
                .Take(4)
                .ToArray();
        }

        // 두 좌표 간의 거리를 계산하는 메서드
        
        private void SortFastPath(ref stDrilling_GroupData paths, bool bSortDir_HorVer, double dStepSize)
        {
            List<stDrilling_ObjectData> pathFast = new List<stDrilling_ObjectData>();

            double dStep = 0.0;
            dStep = dStepSize;

            if (dStep <= 0.0)
            {
                dStep = 0.03;
            }

            if (bSortDir_HorVer)           //  X 방향 Zigzag 이동
            {
                if (paths.m_stDrilling_ObjectData != null)
                {

                    double dMin = paths.m_stDrilling_ObjectData.Min(t => t.dEdgePoint.Min(tt => tt.Y));
                    double dMax = paths.m_stDrilling_ObjectData.Max(t => t.dEdgePoint.Max(tt => tt.Y));

                    bool bAccending = true;


                    for (double iter = dMin; iter <= dMax; iter += dStep)
                    {
                        IOrderedEnumerable<stDrilling_ObjectData> iSorted = null;
                        if (bAccending)
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.Y) >= iter && t.dEdgePoint.Min(tt => tt.Y) < (iter + dStep)).ToList().OrderBy(t => t.dEdgePoint.Min(tt => tt.X));
                        }
                        else
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.Y) >= iter && t.dEdgePoint.Min(tt => tt.Y) < (iter + dStep)).ToList().OrderByDescending(t => t.dEdgePoint.Min(tt => tt.X));
                        }

                        pathFast.AddRange(iSorted);
                        bAccending = !bAccending;
                    }
                }
            }
            else                //  Y 방향 Zigzag 이동
            {
                if (paths.m_stDrilling_ObjectData != null)
                {

                    double dMin = paths.m_stDrilling_ObjectData.Min(t => t.dEdgePoint.Min(tt => tt.X));
                    double dMax = paths.m_stDrilling_ObjectData.Max(t => t.dEdgePoint.Max(tt => tt.X));

                    bool bAccending = true;


                    for (double iter = dMin; iter <= dMax; iter += dStep)
                    {
                        IOrderedEnumerable<stDrilling_ObjectData> iSorted = null;
                        if (bAccending)
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.X) >= iter && t.dEdgePoint.Min(tt => tt.X) < (iter + dStep)).ToList().OrderBy(t => t.dEdgePoint.Min(tt => tt.Y));
                        }
                        else
                        {
                            iSorted = paths.m_stDrilling_ObjectData.Where(t => t.dEdgePoint.Min(tt => tt.X) >= iter && t.dEdgePoint.Min(tt => tt.X) < (iter + dStep)).ToList().OrderByDescending(t => t.dEdgePoint.Min(tt => tt.Y));
                        }

                        pathFast.AddRange(iSorted);
                        bAccending = !bAccending;
                    }

                }
            }
            paths.m_stDrilling_ObjectData = pathFast.ToArray();
        }


        /// <summary>
        /// PreAlign Position을 찾는 함수.
        /// stDividedRegion_GroupData[] inputGroupData = m_stDividedRegion_GroupData; // 예시
        /// PointD leftPoint, rightPoint;
        /// FindEdgePoints(inputGroupData, out leftPoint, out rightPoint);
        /// </summary>
        /// <returns></returns>
        public static void FindEdgePoints(
        stDividedRegion_GroupData[] groupDataArray,
        out PointD leftMostPoint,
        out PointD rightMostPoint)
        {
            double maxY = double.MinValue;
                List<PointD> candidates = new List<PointD>();

            if (groupDataArray == null)
            {
                leftMostPoint = new PointD(0, 0);
                rightMostPoint = new PointD(0, 0);
                return;
            }

            foreach (var group in groupDataArray)
            {
                if (group.dFiducialPos == null)
                    continue;

                foreach (var fiducial in group.dFiducialPos)
                {
                    if (fiducial == null)
                        continue;

                    if (fiducial.Y > maxY)
                    {
                        // 더 큰 Y값을 찾으면 후보를 초기화
                        maxY = fiducial.Y;
                        candidates.Clear();
                        candidates.Add(fiducial);
                    }
                    else if (fiducial.Y == maxY)
        {
            // 같은 Y값이면 후보로 추가
            candidates.Add(fiducial);
        }
                }
            }

            if (candidates.Count == 0)
        {
            leftMostPoint = new PointD(0, 0);
            rightMostPoint = new PointD(0, 0);
            return;
        }

        // X 기준으로 정렬해서 가장 왼쪽과 가장 오른쪽 찾기
        leftMostPoint = candidates.OrderBy(p => p.X).First();
        rightMostPoint = candidates.OrderByDescending(p => p.X).First();
        }


        public static bool TryGetIntersection(PointD p1, PointD p2, PointD p3, PointD p4, out PointD intersection)
        {
            intersection = new PointD();

            // 대각선 1: p1 -> p2
            double a1 = p2.Y - p1.Y;
            double b1 = p1.X - p2.X;
            double c1 = a1 * p1.X + b1 * p1.Y;

            // 대각선 2: p3 -> p4
            double a2 = p4.Y - p3.Y;
            double b2 = p3.X - p4.X;
            double c2 = a2 * p3.X + b2 * p3.Y;

            // 두 직선의 교점 계산
            double determinant = a1 * b2 - a2 * b1;

            if (Math.Abs(determinant) < 1e-10)
            {
                // 두 직선이 평행하거나 겹침
                return false;
            }

            double x = (b2 * c1 - b1 * c2) / determinant;
            double y = (a1 * c2 - a2 * c1) / determinant;

            // 교점 설정
            intersection = new PointD(x, y);
            return true;
        }
        public st4PointAlign_Result Calc_4Point_AlignData(st4PointPosition_Data[] ptDwgPos, st4PointPosition_Data[] ptInspectedPos)
        {
            //  4 Point 위치 (좌측 하단부터 시계방향으로)
            //  P1 : Left Bottom
            //  P2 : Left Top
            //  P3 : Right Top
            //  P4 : Right Bottom

            //  직선 구성 : P2 - P4, P1 - P3

            st4PointAlign_Result m_st4PointAlign_Result = new st4PointAlign_Result();
            m_st4PointAlign_Result.dCenterOffsetX = 0.0;
            m_st4PointAlign_Result.dCenterOffsetY = 0.0;
            m_st4PointAlign_Result.dRotationAngle = 0.0;

            //  도면상 좌표 데이터 모두 존재하는지 체크
            if ((ptDwgPos[0].ptFiducial_Center.X == 0.0) && (ptDwgPos[0].ptFiducial_Center.Y == 0.0) &&
                (ptDwgPos[1].ptFiducial_Center.X == 0.0) && (ptDwgPos[1].ptFiducial_Center.Y == 0.0) &&
                (ptDwgPos[2].ptFiducial_Center.X == 0.0) && (ptDwgPos[2].ptFiducial_Center.Y == 0.0) &&
                (ptDwgPos[3].ptFiducial_Center.X == 0.0) && (ptDwgPos[3].ptFiducial_Center.Y == 0.0))
            {
                return m_st4PointAlign_Result;
            }

            //  비전 검사로 얻은 좌표 데이터 모두 존재하는지 체크
            if ((ptInspectedPos[0].ptFiducial_Center.X == 0.0) && (ptInspectedPos[0].ptFiducial_Center.Y == 0.0) &&
                (ptInspectedPos[1].ptFiducial_Center.X == 0.0) && (ptInspectedPos[1].ptFiducial_Center.Y == 0.0) &&
                (ptInspectedPos[2].ptFiducial_Center.X == 0.0) && (ptInspectedPos[2].ptFiducial_Center.Y == 0.0) &&
                (ptInspectedPos[3].ptFiducial_Center.X == 0.0) && (ptInspectedPos[3].ptFiducial_Center.Y == 0.0))
            {
                return m_st4PointAlign_Result;
            }

            //  도면상좌표 데이터 4개의 교차점이 존재하는지 체크
            if ((((ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y)) -
                ((ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X))) == 0.0)                                //  교차점이 없는 경우
            {
                return m_st4PointAlign_Result;
            }

            //  비전 검사로 얻은 좌표 데이터 4개의 교차점이 존재하는지 체크
            if ((((ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y)) -
                ((ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X))) == 0.0)                                //  교차점이 없는 경우
            {
                return m_st4PointAlign_Result;
            }

            //  도면상 좌표 데이터의 교차점 계산
            double dDwgCrossX = 0.0;
            double dDwgCrossY = 0.0;

            dDwgCrossX = (((ptDwgPos[1].ptFiducial_Center.X * ptDwgPos[3].ptFiducial_Center.Y - ptDwgPos[1].ptFiducial_Center.Y * ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X) -
                        (ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.X * ptDwgPos[0].ptFiducial_Center.Y - ptDwgPos[2].ptFiducial_Center.Y * ptDwgPos[0].ptFiducial_Center.X)) /
                        ((ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y) - (ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X)));
            dDwgCrossY = (((ptDwgPos[1].ptFiducial_Center.X * ptDwgPos[3].ptFiducial_Center.Y - ptDwgPos[1].ptFiducial_Center.Y * ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y) -
                        (ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X * ptDwgPos[0].ptFiducial_Center.Y - ptDwgPos[2].ptFiducial_Center.Y * ptDwgPos[0].ptFiducial_Center.X)) /
                        ((ptDwgPos[1].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X) * (ptDwgPos[2].ptFiducial_Center.Y - ptDwgPos[0].ptFiducial_Center.Y) - (ptDwgPos[1].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y) * (ptDwgPos[2].ptFiducial_Center.X - ptDwgPos[0].ptFiducial_Center.X)));

            //  비전 검사로 얻은 좌표 데이터의 교차점 계산
            double dInspectedCrossX = 0.0;
            double dInspectedCrossY = 0.0;

            dInspectedCrossX = (((ptInspectedPos[1].ptFiducial_Center.X * ptInspectedPos[3].ptFiducial_Center.Y - ptInspectedPos[1].ptFiducial_Center.Y * ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X) -
                        (ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.X * ptInspectedPos[0].ptFiducial_Center.Y - ptInspectedPos[2].ptFiducial_Center.Y * ptInspectedPos[0].ptFiducial_Center.X)) /
                        ((ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y) - (ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X)));
            dInspectedCrossY = (((ptInspectedPos[1].ptFiducial_Center.X * ptInspectedPos[3].ptFiducial_Center.Y - ptInspectedPos[1].ptFiducial_Center.Y * ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y) -
                        (ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X * ptInspectedPos[0].ptFiducial_Center.Y - ptInspectedPos[2].ptFiducial_Center.Y * ptInspectedPos[0].ptFiducial_Center.X)) /
                        ((ptInspectedPos[1].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X) * (ptInspectedPos[2].ptFiducial_Center.Y - ptInspectedPos[0].ptFiducial_Center.Y) - (ptInspectedPos[1].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y) * (ptInspectedPos[2].ptFiducial_Center.X - ptInspectedPos[0].ptFiducial_Center.X)));

            //  도면상 좌표 데이터의 교차점과 비전 검사로 얻은 좌표 데이터의 교차점간 오프셋 거리 계산
            double dOffsetX = 0.0;
            double dOffsetY = 0.0;
            dOffsetX = dDwgCrossX - dInspectedCrossX;
            dOffsetY = dDwgCrossY - dInspectedCrossY;


            //  도면상 좌표 데이터의 교차점과 비전 검사로 얻은 좌표 데이터의 교차점간 회전 각도 계산
            double dAngle = 0.0;
            double dDwgAngle = 0.0;
            double dInspectedAngle = 0.0;
            dDwgAngle = Math.Atan2(ptDwgPos[0].ptFiducial_Center.Y - ptDwgPos[3].ptFiducial_Center.Y, ptDwgPos[0].ptFiducial_Center.X - ptDwgPos[3].ptFiducial_Center.X);
            dInspectedAngle = Math.Atan2(ptInspectedPos[0].ptFiducial_Center.Y - ptInspectedPos[3].ptFiducial_Center.Y, ptInspectedPos[0].ptFiducial_Center.X - ptInspectedPos[3].ptFiducial_Center.X);
            dAngle = dDwgAngle - dInspectedAngle;

            //  결과값 저장  
            //m_st4PointAlign_Result.dRotationCenterX = dDwgCrossX;
            //m_st4PointAlign_Result.dRotationCenterY = dDwgCrossY;

            m_st4PointAlign_Result.dRotationCenterX = ptDwgPos[0].ptFiducial_Center.X;
            m_st4PointAlign_Result.dRotationCenterY = ptDwgPos[0].ptFiducial_Center.Y;

            PointD InspectionCenter;
            TryGetIntersection(
                ptInspectedPos[0].ptFiducial_Center
                , ptInspectedPos[2].ptFiducial_Center
                , ptInspectedPos[1].ptFiducial_Center
                , ptInspectedPos[3].ptFiducial_Center
                , out InspectionCenter);
            PointD DwgCenter;
            TryGetIntersection(
                ptDwgPos[0].ptFiducial_Center
                , ptDwgPos[2].ptFiducial_Center
                , ptDwgPos[1].ptFiducial_Center
                , ptDwgPos[3].ptFiducial_Center
                , out DwgCenter);


            DwgCenter = this.CoordinateTransform(DwgCenter, ptDwgPos[0].ptFiducial_Center.X, ptDwgPos[0].ptFiducial_Center.Y, -dAngle);

            m_st4PointAlign_Result.dCenterOffsetX = InspectionCenter.X - DwgCenter.X;
            m_st4PointAlign_Result.dCenterOffsetY = InspectionCenter.Y - DwgCenter.Y; ;
            m_st4PointAlign_Result.dRotationAngle = dAngle;


            return m_st4PointAlign_Result;
        }

