            switch (m_nScanner_Calibration_Step)
            {
                case (int)ScannerCalibration_Step.None:
                    {

                    }
                    break;

                case (int)ScannerCalibration_Step.Start:
                    {
                        //Test
                        //DrawCalibrationCrosses(3, 3, 2, 2);
