                        // Todo : 조명 디버깅 필요
                        int ch1Val = Equipment.Scanner_Calibration_Illumination_channel_01_Value;
                        int ch2Val = Equipment.Scanner_Calibration_Illumination_channel_02_Value;
                        CommonModule.Instance.Illuminator.SetVolume(ch1Val, 1);
                        CommonModule.Instance.Illuminator.SetVolume(ch2Val, 2);
                        CommonModule.Instance.Illuminator.TurnOnOff(true, 1);
                        CommonModule.Instance.Illuminator.TurnOnOff(true, 2);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.Laser_Off;

                       

                        Log.Write("SLD-200", "Scanner Calibration", "Laser&Scanner Calibration Start");
                    }
                    break;

                case (int)ScannerCalibration_Step.Laser_Off:                                              //  레이저 Off
                    {
                        if (rtc != null)
                        {
                            rtc.CtlLaserOff();
                        }

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.Laser_Off_Check;
                    }
                    break;

                case (int)ScannerCalibration_Step.Laser_Off_Check:                                                  //  레이저 Off 확인
                    {
                        if (rtc != null)
                        {
                            if (rtc.CtlGetStatus(RtcStatus.NotBusy))
                            {
                                Log.Write("SLD-200", "Scanner Calibration", "Laser Off Check");

                                if (Equipment.Machine_LaserType_CO2)
                                {
                                    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.DustCollector_On;
                                }
                                else
                                {
                                    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserShutter_Close;
                                    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserFrequency_Change;
                                }
                            }
                            else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                            {
                                //MessageBox.Show("Error", "Laser Off 실패");
                                Log.Write("SLD-200", "Scanner Calibration", "Laser Off Check 실패.");
                                Alarm alarm = new Alarm();
                                alarm.Title = "Laser Off 실패";
                                alarm.Code = 1001;
                                alarm.Source = Name;
                                alarm.Grade = "Error";
                                alarm.Cause = "Laser Off 실패";
                                AlarmManager.Instance.ShowAlarm(alarm);
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            }
                        }
                        else
                        {
                            strTemp = string.Format("Laser Off Check 실패. (Laser Comm 열리지 않음)"); 
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserShutter_Close:                                                //  Shutter Close
                    {
                        //상부 파워메타로 Shutter 사용 중?
                        workStageParameter.DO_BDS_PowerMeter_FW(true);
                        workStageParameter.DO_BDS_PowerMeter_BW(false);
                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserShutter_Close_Check;
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserShutter_Close_Check:                                          //  Shutter Close 확인
                    {
                        if (!workStageParameter.DI_BDS_PowerMeter_BW_Check() && workStageParameter.DI_BDS_PowerMeter_FW_Check())
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserFrequency_Change;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            MessageBox.Show("Power Meter (Shutter) Close 실패", "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserFrequency_Change:                        //  레이저 Frequency 변경
                    {
                        if ((m_rapidLxLaser_Comm != null) && (Equipment.Scanner_Calibration_LaserFrequency > 0.0))
                        {
                            if (m_rapidLxLaser_Comm.IsOpen)
                            {
                                RapidLxLaserComm_Laser_AmplifierRR_Set(Equipment.Scanner_Calibration_LaserFrequency);
                                TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                                strTemp = string.Format("Scanner Calibration 중 Laser Frequency 변경 시작, Laser Frequency ({0:0.000})", Equipment.Scanner_Calibration_LaserFrequency);
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);
                                
                                TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserFrequency_ChangeCheck;
                            }
                            else
                            {
                                strTemp = string.Format("Scanner Calibration 중 Laser Frequency 변경 실패. (Laser Comm 열리지 않음)");
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);
                                MessageBox.Show(strTemp, "Error");
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            }
                        }
                        else
                        {
                            strTemp = string.Format("Scanner Calibration 중 Laser Frequency 변경 실패. (Laser Comm 준비되지 않았거나, 변경 출력이 0)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserFrequency_ChangeCheck:
                    {
                        const double epsilon = 0.1;// 0.001;// 1e-6;
                        if (Math.Abs(Equipment.Scanner_Calibration_LaserFrequency - m_dLaserComm_ReadSetValue_Amplifier) < epsilon)
                        {
                            strTemp = string.Format("Scanner Calibration 중 Laser Frequency 변경 완료 확인 성공, Laser Frequency ({0:0.000})", Equipment.Scanner_Calibration_LaserFrequency);
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserPower_Change;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Laser Frequency 변경 완료 확인 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserPower_Change:                        //  레이저 Power 변경
                    {
                        if ((m_rapidLxLaser_Comm != null) && (Equipment.Scanner_Calibration_LaserEnergy > 0.0))
                        {
                            if (m_rapidLxLaser_Comm.IsOpen)
                            {
                                RapidLxLaserComm_Laser_OutputEnergy_Set(Equipment.Scanner_Calibration_LaserEnergy);
                                TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                                strTemp = string.Format("Scanner Calibration 중 Laser Power 변경 시작, Laser Power ({0:0.000})", Equipment.Scanner_Calibration_LaserEnergy);
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);

                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserPower_ChangeCheck;
                            }
                            else
                            {
                                strTemp = string.Format("Scanner Calibration 중 Laser Power 변경 실패. (Laser Comm 열리지 않음)");
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);
                                MessageBox.Show(strTemp, "Error");
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            }
                        }
                        else
                        {
                            strTemp = string.Format("Scanner Calibration 중 Laser Power 변경 실패. (Laser Comm 준비되지 않았거나, 변경 출력이 0)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserPower_ChangeCheck:
                    {
                        const double epsilon = 0.001;// 1e-6;
                        if (Math.Abs(Equipment.Scanner_Calibration_LaserEnergy - m_dLaserComm_ReadSetValue_EnergyPercent) < epsilon)
                        {
                            strTemp = string.Format("Scanner Calibration 중 Laser Energy 변경 완료 확인 성공, Laser Energy ({0:0.000})", Equipment.Scanner_Calibration_LaserFrequency);
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.DustCollector_On;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Laser Energy 변경 완료 확인 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.DustCollector_On:                                                //  Dust Collector On
                    {
                        //laserDrillingParameter.DO_DustCollector_OnOff(true);                          //  집진기 동작은 On/Off 스위치로 동작
                        //UV
                        //DustCollector_On((int)nDustCollector.DustCollector_Upper);
                        //DustCollector_On((int)nDustCollector.DustCollector_Lower);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.DustCollector_On_Check;
                    }
                    break;

                case (int)ScannerCalibration_Step.DustCollector_On_Check:
                    {
                        //if (workStageParameter.DI_DustCollector_Fan_Run((int)nDustCollector.DustCollector_Upper) && 
                        //    !workStageParameter.DI_DustCollector_Fan_Fault((int)nDustCollector.DustCollector_Upper) &&
                        //    workStageParameter.DI_DustCollector_Fan_Run((int)nDustCollector.DustCollector_Lower) && 
                        //    !workStageParameter.DI_DustCollector_Fan_Fault((int)nDustCollector.DustCollector_Lower))
                        //{
                        //    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserShutter_Open;
                        //}
                        //else if (workStageParameter.DI_DustCollector_Fan_Fault((int)nDustCollector.DustCollector_Upper) || 
                        //         workStageParameter.DI_DustCollector_Fan_Fault((int)nDustCollector.DustCollector_Lower))
                        //{
                        //    //timer_Motion_Home.Enabled = false;

                        //    MessageBox.Show("Alarm", "Dust Collector 점검 요망\r\n\r\n[Fault Signal 확인]");
                        //    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        //}
                        //else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        //{
                        //    Log.Write("SLD-200", "Auto Run", "집진기 On 실패");
                        //    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        //    MessageBox.Show("Dust Collector On 실패", "Error");
                        //}

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserShutter_Open;
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserShutter_Open:    //  Shutter Open
                    {
                        //상부 파워메타로 Shutter 사용 중?
                        workStageParameter.DO_BDS_PowerMeter_BW(true);
                        workStageParameter.DO_BDS_PowerMeter_FW(false);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.LaserShutter_Open_Check;
                    }
                    break;

                case (int)ScannerCalibration_Step.LaserShutter_Open_Check:                                         //  Shutter Open 확인
                    {
                        if (workStageParameter.DI_BDS_PowerMeter_BW_Check() && !workStageParameter.DI_BDS_PowerMeter_FW_Check())
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.WaterLine_Open;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Power Meter (Shutter) Open 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.WaterLine_Open:                                                //  Water Line Open
                    {
                        workStageParameter.DO_BeamDump_Coolant_Supply(true);                    //  Laser Cooling Valve Open
                        workStageParameter.DO_Scanner_Coolant_Supply(true);                     //  Scanner Cooling Valve Open

                        if (Equipment.Machine_LaserType_CO2)
                        {
                            workStageParameter.DO_Mask_Coolant_Supply(true);                    //  Beam Mask 
                            workStageParameter.DO_VarioScan_Coolant_Supply(true);
                        }

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.WaterLine_Open_Check;
                    }
                    break;

                case (int)ScannerCalibration_Step.WaterLine_Open_Check:                                         //  Water Line Open 확인
                    {
                        if (workStageParameter.IsDO_BeamDump_Coolant_Supply() &&
                            workStageParameter.IsDO_Scanner_Coolant_Supply() &&
                            (!Equipment.Machine_LaserType_CO2 ||
                            Equipment.Machine_LaserType_CO2 &&
                            workStageParameter.IsDO_Mask_Coolant_Supply() &&
                            workStageParameter.IsDO_VarioScan_Coolant_Supply()))
                        {
                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.VerifyCalibrationAreaPos;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_MAIN) > 5000)
                        {
                            strTemp = string.Format("Water Supply Line Open 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.VerifyCalibrationAreaPos:
                    {
                        // cal center 기준 위치로 계산하고 이동하자.
                        double dScannerCalTeachingPosX = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_Scanner_CalPos].Stage_X;
                        double dScannerCalTeachingPosY = stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_Scanner_CalPos].Stage_Y;
                        double dScannerCalAreaWidth = Equipment.Scanner_Calibration_CalAreaWidth;
                        double dScannerCalAreaheight = Equipment.Scanner_Calibration_CalAreaHeight;
                        double dCalPitchOffset = Equipment.Scanner_Calibration_CalPitch;
                        double AreaCenterX = dScannerCalTeachingPosX;
                        double AreaCenterY = dScannerCalTeachingPosY;

                        // [변경] X 영역은 왼쪽부터 시작, Y는 센터 기준 위쪽부터
                        double dScannerCalAreaPosX_Min = AreaCenterX + dCalPitchOffset;
                        double dScannerCalAreaPosX_Max = AreaCenterX + dScannerCalAreaWidth - dCalPitchOffset;

                        double dScannerCalAreaPosY_Min = AreaCenterY + dCalPitchOffset;
                        double dScannerCalAreaPosY_Max = AreaCenterY + (dScannerCalAreaheight / 2) - dCalPitchOffset;

                        // 현재 하고자 하는 캘 사이즈 계산을 위한 값
                        int nRow = Equipment.Scanner_Calibration_rowCount;
                        int nCol = Equipment.Scanner_Calibration_colCount;
                        float fRowInterval = (float)Equipment.Scanner_Calibration_rowInterval;
                        float fColInterval = (float)Equipment.Scanner_Calibration_colInterval;

                        if (Equipment.Scanner_Vision_Offset_Setting_Use == true)
                        {
                            nRow = 1;
                            nCol = 1;
                            fRowInterval = 1;
                            fColInterval = 1;
                        }

                        double dCalWidth = (nCol - 1) * fColInterval;
                        double dCalHeight = (nRow - 1) * fRowInterval;
                        double dCurrentCalCenterX = dCalWidth / 2;
                        double dCurrentCalCenterY = dCalHeight / 2;

                        // [변경] 캘판 교체 시 시작 위치는 티칭 기준 중앙에서 왼쪽으로 반 너비만큼 이동
                        if (bCalChagne) //캘판 교체시.
                        {
                            m_dScannerCalPosX_Last = AreaCenterX - (dCalWidth / 2);  // [변경]
                            m_dScannerCalPosY_Last = AreaCenterY;                    // [변경]
                            //m_dScannerCalPosX_Last = dScannerCalAreaPosX_Min + 1;
                            //m_dScannerCalPosY_Last = dScannerCalAreaPosY_Min + 1;
                        }

                        // 캘 영역 벗어나는지 검사
                        if (m_dScannerCalPosX_Last <= dScannerCalAreaPosX_Min || m_dScannerCalPosX_Last >= dScannerCalAreaPosX_Max ||
                            m_dScannerCalPosY_Last <= dScannerCalAreaPosY_Min || m_dScannerCalPosY_Last >= dScannerCalAreaPosY_Max)
                        {
                            strTemp = string.Format("캘판 범위 벗어났습니다. 캘판을 교체해 주세요.");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                        else
                        {
                            if (bCalChagne) // [변경] 캘판 교체 후 첫 위치는 중앙 티칭 위치에서 계산됨
                            {
                                m_dCurrentCalPosX = m_dScannerCalPosX_Last;
                                m_dCurrentCalPosY = m_dScannerCalPosY_Last;
                                Equipment.Scanner_Calibration_Change = false;
                                bCalChagne = false;
                            }
                            else
                            {
                                // [변경] 이후부터는 X축 방향으로만 피치 간격 이동
                                m_dCurrentCalPosX = m_dScannerCalPosX_Last + dCalWidth + dCalPitchOffset;
                                m_dCurrentCalPosY = m_dScannerCalPosY_Last; // Y 고정
                            }

                            // [유지] 이동할 위치가 cal area를 벗어나는지 확인
                            if (m_dCurrentCalPosX <= dScannerCalAreaPosX_Min || m_dCurrentCalPosX >= dScannerCalAreaPosX_Max ||
                                m_dCurrentCalPosY <= dScannerCalAreaPosY_Min || m_dCurrentCalPosY >= dScannerCalAreaPosY_Max)
                            {
                                strTemp = string.Format("캘판 범위 벗어났습니다. 캘판을 교체해 주세요.");
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);
                                MessageBox.Show(strTemp, "Error");
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            }
                            else
                            {
                                //범위 안에 있다면, 다음 위치로 이동.
                                //이동할 위치를 가지고 가자.
                                //다음 캘리브레이션 위치로 이동.

                                // 정상동작 완료하고 Pos값 넣고 저장하자.... 아니지... Laser 쏘고 완료 되면 
                                // 저장이다. 한 번 Laser 발진 한 곳은 그냥 끝. 
                                // m_dScannerCalPosX_Last <- 이 위치가.. Vision cal 할 수 있는 위치가 되겠다..
                                //m_dScannerCalPosX_Last = m_dCurrentCalPosX;
                                //m_dScannerCalPosY_Last = m_dCurrentCalPosY;

                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.MapDataChange_ScannerCalMap;
                            }
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.MapDataChange_ScannerCalMap:
                    {
                        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                        //  맵 데이터 변경 (기준위치 : Scanner)
                        //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                        //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                        //MapData_Apply((int)nMapData_Type.MapData_Stage_Scanner);            //그냥 이거 사용하면 되지 않나?
                        //MapData_Apply((int)nMapData_Type.MapData_Stage_CalPos_Scanner);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.MapDataFlagCheck_ScannerCalMap;
                    }
                    break;

                case (int)ScannerCalibration_Step.MapDataFlagCheck_ScannerCalMap:                                   //  Scanner Calibration 위치 Map Data 로 변경되었는지 확인
                    {
                        //변위 센서 측정 후 이동은... 확인 후에 하자.
                        if (Equipment.Machine_LaserType_CO2)
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibrationPos;
                        }
                        else
                        {
                            //m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensorPos;
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibrationPos;
                        }

                    }
                    break;

                case (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensorPos:
                    {
                        // Z-Axis Offset Init.
                        m_dZOffset_SocketHeightCheck = 0.0;

                        workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Safety");

                        //  속도 설정 (스트로크 짧은 Z축은 느리게)
                        lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                        lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                        //  Target 위치 변경 : Laser Height Check
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] =
                            vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheckPos].Vision_Z;

                        //MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z,
                        //   workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z], lfVelocity, lfAccDec, lfAccDec);
                        MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z,
                            vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheckPos].Vision_Z, lfVelocity, lfAccDec, lfAccDec);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensorPos_DoneCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensorPos_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z,
                            vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheckPos].Vision_Z))
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_LaserHeightSensorPos;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) >= LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage Z 축, Laser Height Check 높이로 이동 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.StageXY_Move_LaserHeightSensorPos:
                    {
                        //기존 data 첫번째로 진행. 
                        m_nDrillingWork_Group_Count = 0;

                        //  좌표계 (기존)
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = 0.0;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = 0.0;

                        // 참고 주석.
                        //  좌표계 변환 (Stage 좌표계와 Scanner 좌표계를 일치시키지 않을 경우에 사용. Stage 원점 위치에서 Scanner Center 까지의 Offset 거리를 더해서 이동시킨다.)
                        //workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] += Equipment.StageOffset_forDrilling_X;
                        //workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] += Equipment.StageOffset_forDrilling_Y;

                        // 좌표계 변환 (Scanner Calibration 위치) : Stage가 Scanner Center 위치임.
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] += m_dCurrentCalPosX;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] += m_dCurrentCalPosY;

                        //  좌표계 변환 (Scanner 위치 --> Fine Camera 위치)
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] -= Equipment.stOffsetDistance.FromScannerToFineCam.X;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] -= Equipment.stOffsetDistance.FromScannerToFineCam.Y;

                        //  좌표계 변환 (Fine Camera 위치 --> Laser Height Sensor 위치)
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] += Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.X;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] += Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.Y;

                        //  속도 설정
                        lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                        lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                        //아래 구문 해보고 stage Center 위치를 기준으로 하여, Laser Height Sensor 위치로 이동으로 변경 해보자. 
                        xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                        xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];
                        MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_LaserHeightSensorPos_DoneCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.StageXY_Move_LaserHeightSensorPos_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                            MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                        {
                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.Move_LaserHeightSensorPos_StableTime;


                            //m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensor_CalPos;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage XY 축, Laser Height Check 위치로 이동 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                // scanner cal을 위해서 변위 높이가.. 더 낮아져야 할 수도 있다. 티칭 포지션으로 움직여야 한다.
                // 그런데.. 더 낮아지면 간섭 유/무 확인하고 진행해야 한다.!!!
                case (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensor_CalPos:
                    {
                        // Z-Axis Offset Init.
                        m_dZOffset_SocketHeightCheck = 0.0;

                        //  속도 설정 (스트로크 짧은 Z축은 느리게)
                        lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                        lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                        //  Target 위치 변경 : Laser Height Check
                        //workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] =
                        //    vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheckPos].Vision_Z;

                        //-> 아래로 변경해야 하는데 티칭 포지션 만들어야 한다. 
                        //workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] =
                        //    vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheck_CalPos].Vision_Z;

                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] =
                            vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheckPos].Vision_Z;


                        MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z,
                           workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z], lfVelocity, lfAccDec, lfAccDec);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensor_CalPos_DoneCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.StageZ_Move_LaserHeightSensor_CalPos_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z,
                            workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.Move_LaserHeightSensorPos_StableTime;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) >= LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage Z 축, Laser Height Check 높이로 이동 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.Move_LaserHeightSensorPos_StableTime:
                    {
                        if (Equipment.Machine_LaserHeightCheckStableTime_Enable)
                        {
                            if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                            {
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCalHeightValue_Get;
                            }
                        }
                        else
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCalHeightValue_Get;
                        }
                    }
                    break;

                // scanner cal을 위해서 변위 높이가.. 더 낮아져야 할 수도 있다. 티칭 포지션으로 움직여야 한다.
                case (int)ScannerCalibration_Step.ScannerCalHeightValue_Get:
                    {
                        //  Laser Focus 위치에서 Laser Height 값과, 현재 Laser Height Sensor 값의 차이만큼 가공 높이 보정
                        //m_dZOffset_SocketHeightCheck = Equipment.LaserHeightSensor_ReferenceValue_atScannerFocusPosition - m_dLaserHeightSensorSocket_Value;
                        if ((m_dLaserHeightSensorSocket_Value < -4.5) || (m_dLaserHeightSensorSocket_Value > 5.5) || (m_dLaserHeightSensorSocket_Value < -99.9))
                        {
                            m_dZOffset_SocketHeightCheck = 0.0;
                        }
                        else
                        {
                            m_dZOffset_SocketHeightCheck = m_dLaserHeightSensorSocket_Value - Equipment.LaserHeightSensor_ReferenceValue_atScannerFocusPosition;
                        }


                        Log.Write("SLD-200", "Scanner Calibration", $"변위Data: Z={m_dZOffset_SocketHeightCheck}");

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCalHeight_ZOffset_Move;
                    }
                    break;

                case (int)ScannerCalibration_Step.ScannerCalHeight_ZOffset_Move:
                    {
                        m_dHoleLayer_Defocusing = 0.0;// Equipment.stLayerRecipeSet[0].Miscellaneous_DefocusingDistance;

                        strTemp = string.Format("Stage Z 축, Stage 높이 측정 후, Laser Focus 편차 ({0:0.000}), Dofocusing Distance ({1:0.000})",
                                                        m_dZOffset_SocketHeightCheck, m_dHoleLayer_Defocusing); //m_dHoleLayer_Defocusing ??
                        Log.Write("SLD-200", "Scanner Calibration", strTemp);

                        workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                        //  속도 설정
                        lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                        lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                        //  가공 할 Layer 의 Z Offset 값으로 이동
                        //  임시로 0 설정 --> Recipe 에서 값 가져오도록 --> Layer 별로 Defocusing 거리 다르게 설정하도록 해야 함
                        m_dHeightOffset = m_dHoleLayer_Defocusing;

                        //  좌표계 (기존)
                        //workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = MC_Func.MC_GetEncPos((int)WorkStage.nAxis.Z) - m_dOffset;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] =
                            vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_FocusPos].Vision_Z + m_dZOffset_SocketHeightCheck + m_dHeightOffset;

                        MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z],
                                              lfVelocity, lfAccDec, lfAccDec);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        Log.Write("SLD-200", "Scanner Calibration", $"LaserZAxis: Z={workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]}");

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCalHeight_ZOffset_Move_DoneCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.ScannerCalHeight_ZOffset_Move_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z,
                            workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                        {
                            Log.Write("SLD-200", Equipment.User_Name, "Scanner Calibration", "Stage Z 축, Socket 가공 Focus 조정 완료.");

                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibrationPos;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage Z 축, Socket 가공 Focus 조정 실패. (Timeout)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibrationPos:
                    {
                        //좌표 맵을 바꿔줘야 하나?
                        //MapData_Apply((int)nMapData_Type.MapData_Stage_Scanner);            //그냥 이거 사용하면 되지 않나?
                        //MapData_Apply((int)nMapData_Type.MapData_Stage_CalPos_Scanner);
                        MapData_Apply((int)nMapData_Type.MapData_Stage_Scanner);

                        workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                        //  속도 설정
                        lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                        lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                        //stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_Scanner_CalPos].Stage_X;
                        //stWorkStageTeachingPos[(int)WorkStage_TeachingPosList.STAGE_Scanner_CalPos].Stage_Y;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = m_dCurrentCalPosX;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = m_dCurrentCalPosY;

                        xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                        xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                        MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibrationPos_DoneCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibrationPos_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                            MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMark_MarkingStart;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage XY 축, Stage Center 위치로 이동 실패. (Timeout)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.CrossMark_MarkingStart:
                    {
                        //  Cross Mark Marking 시작. //  Cross Mark Marking 함수 넣자.
                        //float fieldsize = Equipment.Scanner_Calibration_FieldSize; //정사각형 Cal. X,Y Size 동일.
                        int nRow = Equipment.Scanner_Calibration_rowCount;
                        int nCol = Equipment.Scanner_Calibration_colCount;
                        float fRowInterval = (float)Equipment.Scanner_Calibration_rowInterval;
                        float fColInterval = (float)Equipment.Scanner_Calibration_colInterval;
                        double dMarkLength = Equipment.Scanner_Calibration_CrossMarkLength;

                        if (Equipment.Scanner_Vision_Offset_Setting_Use == true)
                        {
                            // 1x1로 설정.: Laser <-> Scanner Offset Setting
                            nRow = 1;
                            nCol = 1;
                            fRowInterval = 1;
                            fColInterval = 1;
                        }

                        //Laser & Scanner 준비 상태 확인 필요. (발진 가능 여부 및 셋팅 값)
                        if (Equipment.Machine_LaserType_CO2)
                        {
                            if (Equipment.Scanner_Vision_Offset_Setting_Use == true)
                            {
                                //걍 무조건 Closs로
                                DrawCalibrationCrosses(nRow, nCol, fRowInterval, fColInterval, dMarkLength);
                            }
                            else
                            {
                                if (Equipment.Scanner_Calibration_MarkType_Cross)
                                {
                                    DrawCalibrationCrosses(nRow, nCol, fRowInterval, fColInterval, dMarkLength);
                                }
                                else //Circle
                                {
                                    DrawCalibrationArc(nRow, nCol, fRowInterval, fColInterval);
                                }
                            }
                        }
                        else //UV
                        {
                            if (Equipment.Scanner_Vision_Offset_Setting_Use == true)
                            {
                                //걍 무조건 Closs로
                                DrawCalibrationCrosses(nRow, nCol, fRowInterval, fColInterval, dMarkLength);
                            }
                            else
                            {
                                if (Equipment.Scanner_Calibration_MarkType_Cross)
                                {
                                    DrawCalibrationCrosses(nRow, nCol, fRowInterval, fColInterval, dMarkLength);
                                }
                                else //Circle
                                {
                                    DrawCalibrationArc(nRow, nCol, fRowInterval, fColInterval);
                                }
                            }
                        }

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMark_MarkingComplete;
                    }
                    break;

                case (int)ScannerCalibration_Step.CrossMark_MarkingComplete:
                    {
                        if (rtc.CtlGetStatus(RtcStatus.NotBusy))
                        {
                            //dScannerCalPosX_Last 어디에 저장해 놓고 써야할지...
                            m_dScannerCalPosX_Last = m_dCurrentCalPosX;
                            m_dScannerCalPosY_Last = m_dCurrentCalPosY;
                            Scanner_Calibration_Option_Save();

                            Log.Write("SLD-200", "Scanner Calibration", "Scanner Calibration, Cross Mark 가공 완료");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.MapDataChange_FineCamMap;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Cross Mark Marking 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;


                // 여기부터는 Fine Camera Seq.
                case (int)ScannerCalibration_Step.MapDataChange_FineCamMap:
                    {
                        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                        //  맵 데이터 변경 (기준위치 : Scanner)
                        //  기준위치로 보낼 때, 맵데이터를 변경한 후 보낸다.
                        //  그 외에는, 위치로 보낸 후 맵데이터를 변경한다.
                        MapData_Apply((int)nMapData_Type.MapData_Stage_CalPos_FineCam);

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.MapDataFlagCheck_FineCamMap;
                    }
                    break;

                case (int)ScannerCalibration_Step.MapDataFlagCheck_FineCamMap: //  Fine Camera 위치 Map Data 로 변경되었는지 확인
                    {
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_CrossMarkCenterPos;
                    }
                    break;

                case (int)ScannerCalibration_Step.StageXY_Move_CrossMarkCenterPos:
                    {
                        workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                        //  좌표계 (기존) :: 현재값 기준으로 모션이동
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] =
                            MC_Func.MC_GetEncPos((int)WorkStage.nAxis.X) - Equipment.stOffsetDistance.FromScannerToFineCam.X;
                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] =
                            MC_Func.MC_GetEncPos((int)WorkStage.nAxis.Y) - Equipment.stOffsetDistance.FromScannerToFineCam.Y;

                        MapData_Apply((int)nMapData_Type.MapData_Stage_CalPos_FineCam);

                        //  속도 설정
                        lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                        lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                        xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                        xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];
                        MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_CrossMarkCenterPos_DoneCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.StageXY_Move_CrossMarkCenterPos_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                            MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                        {
                            Log.Write("SLD-200", "Scanner Calibration", "Stage XY축, 가공 Center 위치로 이동 완료.");

                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensation_StartPosition_Set;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage XY축, 가공 Center 위치로 이동 실패. (Timeout)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                    }
                    break;

                //여기부터 카메라로 + Mark 찾아야함.
                //  Scanner 보정 시작 위치 설정
                case (int)ScannerCalibration_Step.ScannerCompensation_StartPosition_Set:
                    {
                        // Todo : 조명 디버깅 필요 
                        int ch1Val = Equipment.Scanner_Calibration_Illumination_channel_01_Value;
                        int ch2Val = Equipment.Scanner_Calibration_Illumination_channel_02_Value;
                        CommonModule.Instance.Illuminator.SetVolume(ch1Val, 1);
                        CommonModule.Instance.Illuminator.SetVolume(ch2Val, 2);
                        CommonModule.Instance.Illuminator.TurnOnOff(true, 1);
                        CommonModule.Instance.Illuminator.TurnOnOff(true, 2);

                        XyzCoordinate currentPos = new XyzCoordinate();
                        if (scannerCompensator == null || scannerCompensator.Stage == null)
                        {
                            Log.Write("ScannerCalibration", "ScannerCompensator or Stage is null");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            break;
                        }

                        // 1. 현재 위치 획득
                        if (scannerCompensator.Stage.GetCommandPosition(ref currentPos) != 0)
                        {
                            strTemp = string.Format("Stage 현재 위치를 가져올 수 없습니다.");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            break;

                        }
                        // 2. Config에 현재 위치 저장
                        scannerCompensator.Config.GridPositions[(int)ScannerCompensator.GridXyMotionPositionKeys.StartPosition].Coordinate = currentPos;
                        // 3. 로그 출력 및 다음 단계
                        Log.Write("SLD-200", "Scanner Calibration", $"Scanner 보정 시작 위치 저장 완료: X={currentPos.X:0.000}, Y={currentPos.Y:0.000}, Z={currentPos.Z:0.000}");

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_MarkFind_Ready;
                    }
                    break;


                case (int)ScannerCalibration_Step.CrossMarkCenter_MarkFind_Ready:
                    {
                        //  얼라인 마크 위치를 찾기 위한 데이터 세팅
                        //  마크 1개만 찾기 위한 설정
                        //  이거 안해도 될꺼 같지만..흠...
                        m_nFindAlignMarkType = (int)AlignMarkType.ALIGN_1STMARK;                                //  요걸로 하면 마크 1개만 찾고 끝.

                        //  얼라인 마크 위치 평균 계산
                        m_nCrossMark_AlignMarkCount_Max = 3;                            //  얼라인 마크 검사 최대 회수. (평균 계산용)
                        m_nCrossMark_AlignMark_Count = 0;                               //  얼라인 마크 개수. (평균 계산용)
                        m_pCrossMark_AlignMarkPosition_Sum = new PointD(0, 0);          //  얼라인 마크 위치 누적. (평균 계산용)
                        m_pCrossMark_AlignMarkPosition_Average = new PointD(0, 0);      //  얼라인 마크 위치 누적. (평균 계산용)

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_Find;
                    }
                    break;

                case (int)ScannerCalibration_Step.CrossMarkCenter_Find:
                    {
                        Log.Write("SLD-200", "Scanner Calibration", "CrossMarkCenter_Find, Center 검출 시작");

                        m_nVisionAligner_Type = (int)Aligner_Type.Aligner_FineCam;

                        Equipment.Vision_SpiralMove_Use = false;                                        //  돌면서 찾지 않음.
                        Equipment.MachineStop_byUser = false;
                        int result = 0;

                        // scannerCompensator가 null이거나 Stage가 없는 경우 예외 처리
                        if (scannerCompensator == null || scannerCompensator.Stage == null)
                        {
                            strTemp = string.Format("scannerCompensator 또는 Stage가 null입니다.");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            break;
                        }

                        //Center 찾고 진행.
                        result = scannerCompensator.RunSearchMark();
                        if (result == 1)
                        {
                            double markPositionX = scannerCompensator.ResultPosition.X;
                            double markPositionY = scannerCompensator.ResultPosition.Y;

                            Equipment.MachineStop_byUser = false;
                            Log.Write("SLD-200", "Scanner Calibration",
                                        $"마크 위치: X={markPositionX}, Y={markPositionY}");

                            // 다음 단계로 진행
                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_FindResultCheck;
                        }
                        else
                        {
                            strTemp = string.Format("마크를 찾을 수 없습니다.");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);

                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.CrossMarkCenter_Find_Wait:
                    {
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_FindResultCheck;
                    }
                    break;

                case (int)ScannerCalibration_Step.CrossMarkCenter_FindResultCheck:
                    {
                        Log.Write("SLD-200", "Scanner Calibration", "CrossMarkCenter_FindResultCheck, Center 검출 확인");

                        // scannerCompensator에서 이전 검색 결과 가져오기
                        PatternMatchingResult result = scannerCompensator.GetResult();
                        if (result == null || result.Values.Count == 0)
                        {
                            strTemp = string.Format("반복하여 마크 서치 중 - NG (마크를 찾을 수 없음)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_Find;
                            
                        }
                        else
                        {
                            // 첫 번째 마크 위치 가져오기
                            //double markX = result.Values[0].X;
                            //double markY = result.Values[0].Y;
                            //ResultPosition <- 모터 값으로 가져와서 계산.
                            double markX = scannerCompensator.ResultPosition.X;
                            double markY = scannerCompensator.ResultPosition.Y;
                            if (markX == 0 || markY == 0)
                            {
                                strTemp = string.Format("반복하여 마크 서치 중 - NG (위치값 0)");
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);
                                MessageBox.Show(strTemp, "Error");
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_Find;

                            }
                            else
                            {
                                m_pCrossMark_AlignMarkPosition_Sum.X += markX;
                                m_pCrossMark_AlignMarkPosition_Sum.Y += markY;

                                // 평균 계산을 위해 반복
                                m_nCrossMark_AlignMark_Count++;
                                if (m_nCrossMark_AlignMark_Count < m_nCrossMark_AlignMarkCount_Max)
                                {
                                    m_nFindAlignMarkType = (int)AlignMarkType.ALIGN_1STMARK;
                                    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_Find;
                                }
                                else
                                {
                                    m_pCrossMark_AlignMarkPosition_Average.X = m_pCrossMark_AlignMarkPosition_Sum.X / m_nCrossMark_AlignMark_Count;
                                    m_pCrossMark_AlignMarkPosition_Average.Y = m_pCrossMark_AlignMarkPosition_Sum.Y / m_nCrossMark_AlignMark_Count;

                                    if (Math.Abs(m_pCrossMark_AlignMarkPosition_Average.X - markX) <= 0.05 &&
                                        Math.Abs(m_pCrossMark_AlignMarkPosition_Average.Y - markY) <= 0.05)
                                    {
                                        Log.Write("SLD-200", Equipment.User_Name, "Scanner Calibration", "Cross Mark 평균값 OK");
                                        m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X = m_pCrossMark_AlignMarkPosition_Average.X;
                                        m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y = m_pCrossMark_AlignMarkPosition_Average.Y;

                                        strTemp = string.Format("AvgX: {0:0.000}, Avg Y: {1:0.000}, LastX: {2:0.000}, LastY: {3:0.000}",
                                            m_pCrossMark_AlignMarkPosition_Average.X,
                                            m_pCrossMark_AlignMarkPosition_Average.Y,
                                            markX,
                                            markY);
                                        Log.Write("SLD-200", Equipment.User_Name, "Scanner Calibration", strTemp);
                                    }
                                    else
                                    {
                                        Log.Write("SLD-200", Equipment.User_Name, "Scanner Calibration", "Cross Mark 평균값 NG");
                                        strTemp = string.Format("AvgX: {0:0.000}, Avg Y: {1:0.000}, LastX: {2:0.000}, LastY: {3:0.000}",
                                            m_pCrossMark_AlignMarkPosition_Average.X,
                                            m_pCrossMark_AlignMarkPosition_Average.Y,
                                            markX,
                                            markY);
                                        Log.Write("SLD-200", Equipment.User_Name, "Scanner Calibration", strTemp);

                                        m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X = markX;
                                        m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y = markY;
                                    }

                                    m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_XYAlignData_Calc;
                                }
                            }
                        }
                        
                        // 1분 동안 마크를 찾지 못할 경우
                        if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) >= LaserScannerCalTimeout * 2) //10초 
                        {
                            MC_Func.MC_MotorStop((int)nAxis.X, 2000);
                            MC_Func.MC_MotorStop((int)nAxis.Y, 2000);
                            MC_Func.MC_MotorStop((int)nAxis.Z, 2000);

                            strTemp = string.Format("작업 중지. (Cross Mark 검출 시간 초과)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }

                    }
                    break;

                case (int)ScannerCalibration_Step.CrossMarkCenter_XYAlignData_Calc:
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Scanner Calibration", "Cross Mark XY 보정량 계산");

                        PatternMatchingResult result = scannerCompensator.GetResult();
                        if (result == null || result.Values.Count == 0)
                        {
                            strTemp = string.Format("Cross Mark 데이터를 가져오지 못했습니다.");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }
                        else
                        {
                            //현재 위치 포지션과 비교해서 해야 하는거 아닌가?
                            double dCurrentMotorPosX = MC_Func.MC_GetEncPos((int)nAxis.X);
                            double dCurrentMotorPosY = MC_Func.MC_GetEncPos((int)nAxis.Y);
                            //double markX = scannerCompensator.ResultPosition.X;
                            //double markY = scannerCompensator.ResultPosition.Y;
                            
                            // Delta 계산
                            //deltaX = result.Values[0].X - m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X;
                            //deltaY = result.Values[0].Y - m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y;
                            deltaX = dCurrentMotorPosX - m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].X;
                            deltaY = dCurrentMotorPosY - m_forAlign_Data[(int)AlignParam.RESULTPOS_FIRSTMARK].Y;

                            // 허용 오차 값 가져오기
                            double allowableXY = 0.5;   //3.0; //Config.ParamConfig.ReticleAutoCal_UpperVision_Allowable_XY;

                            // 판정: 허용 오차 범위 내인지 확인
                            if (Math.Abs(deltaX) <= allowableXY &&
                                Math.Abs(deltaY) <= allowableXY)
                            {
                                Log.Write("SLD-200", "Scanner Calibration",
                                          $"Cross Mark XY 위치가 카메라 센터에서 오차범위 이내에 있음 (DeltaX: {deltaX}, DeltaY: {deltaY})");

                                // Fine Camera와 Scanner Offset 확인 모드일 경우 Offset 값 재설정
                                // Scanner Calibration 모드일 경우, 15x15 가공 위치의 마크 검사를 진행
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_XYAlign_CorrectionMove;
                            }
                            else
                            {
                                strTemp = string.Format($"Cross Mark XY 위치가 허용 오차를 벗어남 (DeltaX: {deltaX}, DeltaY: {deltaY}, Allowable: {allowableXY})");
                                Log.Write("SLD-200", "Scanner Calibration", strTemp);
                                MessageBox.Show(strTemp, "Error");
                                m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                                return AlarmPost(AlarmKey.ScannerCalibration_Fail);

                            }
                        }
                    }
                    break;

                //  XY 보정 이동 (카메라 Center 로)
                case (int)ScannerCalibration_Step.CrossMarkCenter_XYAlign_CorrectionMove:
                    {
                        workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                        Equipment.Scanner_Vision_Offset_Setting_X = deltaX;
                        Equipment.Scanner_Vision_Offset_Setting_Y = deltaY;

                        //deltaX, deltaY값이 2mm 이상이면 실패 인터락 추가 해줘.
                        // 2mm 이상일 경우 실패 인터락 처리
                        if (Math.Abs(deltaX) > 2.0 || Math.Abs(deltaY) > 2.0)
                        {
                            strTemp = string.Format($"Cross Mark XY위치가 허용 오차를 벗어남 (DeltaX: {deltaX}, DeltaY: {deltaY})");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);

                        }
                        else
                        {
                            // 좌표계 설정
                            workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] =
                                MC_Func.MC_GetEncPos((int)WorkStage.nAxis.X) + (deltaX * -1); //X는 -
                            workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] =
                                MC_Func.MC_GetEncPos((int)WorkStage.nAxis.Y) + deltaY;

                            // 속도 설정
                            lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                            lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                            xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                            xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];
                            MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_XYAlign_CorrectionMove_DoneCheck;
                        }
                    }
                    break;

                //  XY 보정 이동 완료 확인
                case (int)ScannerCalibration_Step.CrossMarkCenter_XYAlign_CorrectionMove_DoneCheck:
                    {
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                            MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                        {
                            Log.Write("SLD-200", "Scanner Calibration", "Stage XY축, 보정 Center 위치로 이동 완료.");

                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.CrossMarkCenter_XYAlign_Retry;

                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage XY축, 보정 Center 위치로 이동 실패. (Timeout)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }
                    }
                    break;

                //  Mark 찾기부터 다시 시작
                case (int)ScannerCalibration_Step.CrossMarkCenter_XYAlign_Retry:
                    {
                        if (Equipment.Scanner_Vision_Offset_Setting_Use == true)
                        {
                            deltaX = Equipment.Scanner_Vision_Offset_Setting_X;
                            deltaY = Equipment.Scanner_Vision_Offset_Setting_Y;

                            MessageBox.Show("OK: Cross Mark XY 위치.\n" +
                                "DeltaX: {deltaX}, DeltaY: {deltaY}", "Completed",
                                MessageBoxButtons.OK, MessageBoxIcon.Information);

                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.Complete;
                        }
                        else
                        {
                            //우선 패스.
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibration_RightTopPos;
                        }
                    }
                    break;

                //  가공된 영역의 우측 상단 모서리 위치로 이동 (이동 거리, X: Pitch * (Row - 1) / 2, Y: Pitch * (Col - 1) / 2)
                case (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibration_RightTopPos:
                    {
                        if (scannerCompensator == null || scannerCompensator.Stage == null)
                        {
                            strTemp = string.Format("ScannerCompensator or Stage is null");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            break;
                        }

                        //Data 불러와서 넣어야함.
                        Point point = new Point(0, 0);
                        point.X = Equipment.Scanner_Calibration_colCount;
                        point.Y = Equipment.Scanner_Calibration_rowCount;
                        scannerCompensator.Config.Count = point;
                        scannerCompensator.Config.PitchDistanceX = Equipment.Scanner_Calibration_colInterval;
                        scannerCompensator.Config.PitchDistanceY = Equipment.Scanner_Calibration_rowInterval;

                        double dCurrentPosX = MC_Func.MC_GetEncPos((int)nAxis.X);
                        double dCurrentPosY = MC_Func.MC_GetEncPos((int)nAxis.Y);

                        // 우측 상단 기준으로 StartPosition 계산
                        double startX = dCurrentPosX - ((scannerCompensator.Config.Count.X - 1) * scannerCompensator.Config.PitchDistanceX) / 2.0;
                        double startY = dCurrentPosY - ((scannerCompensator.Config.Count.Y - 1) * scannerCompensator.Config.PitchDistanceY) / 2.0;
                        double startZ = 0.0;

                        scannerCompensator.Config.GridPositions[(int)ScannerCompensator.GridXyMotionPositionKeys.StartPosition].X = startX;
                        scannerCompensator.Config.GridPositions[(int)ScannerCompensator.GridXyMotionPositionKeys.StartPosition].Y = startY;
                        scannerCompensator.Config.GridPositions[(int)ScannerCompensator.GridXyMotionPositionKeys.StartPosition].Z = startZ;

                        // 1. 기준 좌표 획득
                        XyzCoordinate startPos =
                            scannerCompensator.Config.GridPositions[(int)ScannerCompensator.GridXyMotionPositionKeys.StartPosition].Coordinate;

                        // 2. 이동 대상 좌표 계산 (우측 상단 기준)
                        double moveX = startPos.X;// + ((scannerCompensator.Config.Count.X - 1) * scannerCompensator.Config.PitchDistanceX) / 2.0;
                        double moveY = startPos.Y;// - ((scannerCompensator.Config.Count.Y - 1) * scannerCompensator.Config.PitchDistanceY) / 2.0;

                        // 3. Offset 적용 (스캐너 ↔ 파인캠) //파인캠 센터와서 수행하니깐 필요없다
                        deltaX = moveX;// - Equipment.stOffsetDistance.FromScannerToFineCam.X;
                        deltaY = moveY;// - Equipment.stOffsetDistance.FromScannerToFineCam.Y;

                        // 4. 현재 위치 기준 보정 
                        workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X] = deltaX;
                        //MC_Func.MC_GetEncPos((int)WorkStage.nAxis.X) + deltaX;

                        workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y] = deltaY;
                        //MC_Func.MC_GetEncPos((int)WorkStage.nAxis.Y) + deltaY;

                        // 5. 이동 속도 설정
                        double velocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                        double accdec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                        // 6. 이동 실행
                        xyInterpolatedCoordinate.X = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X];
                        xyInterpolatedCoordinate.Y = workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y];

                        MC_Func.MovePosition(xyInterpolatedCoordinate, velocity, accdec, accdec);

                        // 7. 타이머 시작 (옵션)
                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibration_RightTopPos_DoneCheck;
                    }
                    break;

                //  가공된 영역의 우측 상단 모서리 위치로 이동 완료 확인
                case (int)ScannerCalibration_Step.StageXY_Move_ScannerCalibration_RightTopPos_DoneCheck:
                    {
                        // Stage XY축 도착 여부 확인
                        if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.X]) &&
                            MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) &&
                            MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Y]))
                        {
                            Log.Write("SLD-200", "Scanner Calibration", "Stage XY축, 우측 상단 위치로 이동 완료.");

                            TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensator_Start;
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout)
                        {
                            strTemp = string.Format("Stage XY축, 우측 상단 위치로 이동 실패. (Timeout)");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }
                    }
                    break;

                //  Scanner 보정 시작       
                case (int)ScannerCalibration_Step.ScannerCompensator_Start:
                    {
                        if (scannerCompensator == null)
                        {
                            strTemp = string.Format("ScannerCompensator is null");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }

                        Log.Write("SLD-200", "Scanner Calibration", "ScannerCompensator 보정 시작 (OnWork)");

                        // 내부적으로 RunSearchGridXy → SearchGridXy 자동 수행
                        taskRunScannerConpensation = Task.Factory.StartNew(() =>
                        {
                            scannerCompensator.SetRunStatus(RunStatus.Run);
                            int nRet = scannerCompensator.OnWork();
                            if(nRet != 0)
                            {
                                m_ScannerCalibration_Start = false;
                                AlarmPost(AlarmKey.ScannerCalibration_Fail);
                            }
                        });

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensator_Wait;

                    }
                    break;


                case (int)ScannerCalibration_Step.ScannerCompensator_Wait:
                    {
                        int ret = -1;
                        if (taskRunScannerConpensation != null && taskRunScannerConpensation.IsCompleted)
                        {
                            taskRunScannerConpensation.Dispose();
                            taskRunScannerConpensation = null;
                            ret = 0;
                        }
                        else
                        {
                            break;
                        }

                        if (ret != 0)
                        {
                            strTemp = string.Format("ScannerCompensator.OnWork() 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }
                        else
                        {
                            Log.Write("SLD-200", "Scanner Calibration", "ScannerCompensator 보정 완료");

                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensator_Complete;
                        }
                    }
                    break;

                case (int)ScannerCalibration_Step.ScannerCompensator_Complete:
                    {
                        TickCount_Start((int)TickType.TICK_LASER_SCANNER_CAL);

                        Log.Write("SLD-200", "Scanner Calibration", "Scanner 보정 데이터 수집 완료");

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensatedData_Check;
                    }
                    break;

                //  Scanner 보정 데이터 확인 (오차 체크하여, 오차범위 이내이면 OK, 아니면 다시 보정)
                case (int)ScannerCalibration_Step.ScannerCompensatedData_Check:
                    {
                        if (Equipment.Scanner_Calibration_Convert == 1)
                        {
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensatedData_Correction;
                        }
                        else if (Equipment.Scanner_Calibration_Convert == -1)
                        {
                            //실패.
                            strTemp = string.Format("Scanner 보정 데이터 확인 실패");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Error");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                            return AlarmPost(AlarmKey.ScannerCalibration_Fail);
                        }
                        else if (TickCount_Elapsed((int)TickType.TICK_LASER_SCANNER_CAL) > LaserScannerCalTimeout * 12) // 60초 초과시 실패 처리 (1분)
                        {
                            Log.Write("SLD-200", "Scanner Calibration", "Scanner 보정 데이터 확인 실패. (Timeout)");
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                            MessageBox.Show("Scanner 보정 데이터 확인 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }
                    }
                    break;

                
                case (int)ScannerCalibration_Step.ScannerCompensatedData_Correction:
                    {
                        //  Scanner 보정 데이터 보정 
                        //cal 파일 변경 -> GUI에서 수동
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensatedData_CorrectionFile_Convert;
                    }
                    break;

                
                case (int)ScannerCalibration_Step.ScannerCompensatedData_CorrectionFile_Convert:
                    {
                        //  Scanner 보정 데이터 Convert (보정 데이터로 ct5 파일 생성) -> GUI에서 수동
                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.ScannerCompensatedData_CorrectionFile_Reset;
                    }
                    break;

                
                case (int)ScannerCalibration_Step.ScannerCompensatedData_CorrectionFile_Reset:
                    {
                        //  Scanner 보정 데이터 Reset (보정 데이터 초기화)
                        int nScannerCalRetry = 0;
                        int nScannerCalRetryMax = 0;
                        if (nScannerCalRetry < nScannerCalRetryMax)
                        {
                            nScannerCalRetry++;
                            //m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.MapDataChange_FineCamMap;

                            strTemp = string.Format("ScannerCalibration_Step 완료");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Completed", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;

                        }
                        else
                        {
                            strTemp = string.Format("ScannerCalibration_Step 완료");
                            Log.Write("SLD-200", "Scanner Calibration", strTemp);
                            MessageBox.Show(strTemp, "Completed", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                        }
                    }
                    break;
                case (int)ScannerCalibration_Step.Complete:
                    {

                        m_nScanner_Calibration_Step = (int)ScannerCalibration_Step.None;
                    }
                    break;
            }

            return 0;
        }


        void Run_LaserHeightCheck_Func()
        {
            int m_nStableTime = 500;
            double m_dMarkSpeed = 10.0;
            double m_dMarkLength = 0.1;

            double m_dCurPos_Y = 0.0;
            double m_dCurPos_X = 0.0;

            double lfVelocity = 0.0;
            double lfAccDec = 0.0;

            switch (m_nLaserHeightCheck_Step)
            {
                case (int)LaserHeightCheck_Step.Start:
                    //On_LogFile_Add(LOG_OPERATION, "Lens Focus Check 루틴, 시작.");
                    //Display_Event("Lens Focus Check 루틴 : 시작.");

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Laser Height Check, 시작");

                    m_bLaserHeightCheck_Complete = false;
                    m_dLaserHeightCheck_Value = 0.0;

                    m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.StageZ_MoveFocusPos;
                    break;


                case (int)LaserHeightCheck_Step.StageZ_MoveFocusPos:                                            //  Stage Z 축, 카메라 Focus 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, Laser Height Check 위치로 이동 시작");

                    workStageParameter.stWorkStagePosParam = workStageParameter.GetPositionInformation("Processing");

                    workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z] = vision.stVisionTeachingPos[(int)Vision.Vision_TeachingPosList.Laser_Sensor_HeightCheckPos].Vision_Z;

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Speed_Fine;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;

                    MC_Func.MC_MovePosition((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z], lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_LASER_FOCUS);

                    m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.StageZ_MoveFocusPos_DoneCheck;
                    break;


                case (int)LaserHeightCheck_Step.StageZ_MoveFocusPos_DoneCheck:                                  //  Stage Z 축, 카메라 Focus 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.Z) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Z, workStageParameter.stWorkStagePosParam.dTarget[(int)WorkStageParameter.MotionKey.Z]))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, Laser Height Check 위치로 이동 완료");

                        m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.StageXY_LaserHeightSensor_OffsetMove;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_FOCUS) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage Z 축, Laser Height Check 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_LaserDrillingWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.None;

                        MessageBox.Show("Stage Z 축, Laser Height Check 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)LaserHeightCheck_Step.StageXY_LaserHeightSensor_OffsetMove:                              //  Stage XY 축, Laser Height Sensor Offset 위치로 이동

                    Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Laser Height Check 위치로 이동 시작");

                    //  속도 설정
                    lfVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Speed_Coarse;
                    lfAccDec = Equipment.stAxisParam[(int)WorkStage.nAxis.X].Common_Acceleration_Coarse;

                    if (m_nLaserHeightCheck_Camera == (int)nCameraType.Cam_HighRes)                 //  Fine Camera
                    {
                        xyInterpolatedCoordinate.X = MC_Func.MC_GetEncPos((int)nAxis.X) + Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.X;
                        xyInterpolatedCoordinate.Y = MC_Func.MC_GetEncPos((int)nAxis.Y) + Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.Y;
                    }
                    else if (m_nLaserHeightCheck_Camera == (int)nCameraType.Cam_LowRes)             //  Coarse Camera
                    {
                        xyInterpolatedCoordinate.X = MC_Func.MC_GetEncPos((int)nAxis.X) + Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.X + Equipment.stOffsetDistance.FromFineCamToCoarseCam.X;
                        xyInterpolatedCoordinate.Y = MC_Func.MC_GetEncPos((int)nAxis.Y) + Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.Y + Equipment.stOffsetDistance.FromFineCamToCoarseCam.Y;
                    }
                    else                                                                            //  선택 안하면 High Res Camera 로...
                    {
                        xyInterpolatedCoordinate.X = MC_Func.MC_GetEncPos((int)nAxis.X) + Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.X;
                        xyInterpolatedCoordinate.Y = MC_Func.MC_GetEncPos((int)nAxis.Y) + Equipment.stOffsetDistance.FromFineCamToLaserHeightSensor.Y;
                    }

                    MC_Func.MovePosition(xyInterpolatedCoordinate, lfVelocity, lfAccDec, lfAccDec);

                    TickCount_Start((int)TickType.TICK_LASER_FOCUS);

                    m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.StageXY_LaserHeightSensor_OffsetMove_DoneCheck;
                    break;


                case (int)LaserHeightCheck_Step.StageXY_LaserHeightSensor_OffsetMove_DoneCheck:                 //  Stage XY 축, Laser Height Sensor Offset 위치로 이동 완료 확인

                    if (MC_Func.MC_GetDone((int)WorkStage.nAxis.X) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.X, xyInterpolatedCoordinate.X) &&
                        MC_Func.MC_GetDone((int)WorkStage.nAxis.Y) && MC_Func.MC_PosTolerance((int)WorkStage.nAxis.Y, xyInterpolatedCoordinate.Y))
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Laser Height Check 위치로 이동 완료");

                        TickCount_Start((int)TickType.TICK_LASER_FOCUS);

                        m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.LaserHeightCheck_StableTime;
                    }
                    else if (TickCount_Elapsed((int)TickType.TICK_LASER_FOCUS) > 60000)
                    {
                        Log.Write("SLD-200", Equipment.User_Name, "Auto Run", "Stage XY 축, Laser Height Check 위치로 이동 실패. (Timeout)");

                        //  알람 정지 (LED Bar - Red Blink)
                        Equipment.MachineStop_byAlarm = true;

                        //timer_LaserDrillingWork.Enabled = false;
                        //m_btimer_Motion_Home_Stop = true;

                        m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.None;

                        MessageBox.Show("Stage XY 축, Stage Center 위치로 이동 실패", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    break;


                case (int)LaserHeightCheck_Step.LaserHeightCheck_StableTime:                                     //  Stage 이동 후 안정화 시간

                    if (Equipment.Machine_LaserHeightCheckStableTime_Enable)
                    {
                        if (TickCount_Elapsed((int)TickType.TICK_LASER_FOCUS) > Equipment.Machine_LaserHeightCheckStableTime)
                        {
                            m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.LaserHeightValue_Get;
                        }
                    }
                    else
                    {
                        m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.LaserHeightValue_Get;
                    }
                    break;


                case (int)LaserHeightCheck_Step.LaserHeightValue_Get:                               //  Laser Height Sensor 값 읽기

                    m_dLaserHeightCheck_Value = m_dLaserHeightSensorSocket_Value;

                    m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.Complete;
                    break;


                case (int)LaserHeightCheck_Step.Complete:
                    m_bLaserHeightCheck_Complete = true;

                    m_nLaserHeightCheck_Step = (int)LaserHeightCheck_Step.None;
                    break;
            }
        }

        // Todo : 아래 함수. SpiralLabScanner 정상 동작하면 지우고 옮기자.
        public bool DrawCalibrationCrosses(int rows, int cols, float pitchX, float pitchY, double markLength = 0.5)
        {
            if (rows <= 0 || cols <= 0)
                throw new ArgumentException("Rows and columns must be greater than zero.");

            bool bRtn = false;

            float crossSize = (float)Equipment.Scanner_Calibration_CrossMarkLength; //1.0f; //(float)markLength; 

            if (Equipment.Machine_LaserType_CO2)
            {
                float fFrequency = (float)Equipment.Scanner_Calibration_LaserFrequency;
                float fPulseWidth = (float)Equipment.Scanner_Calibration_LaserPulseWidth;    //2.6f;

                if (fFrequency / 2 <= fPulseWidth)
                    fPulseWidth = fFrequency / 2;
                if (fFrequency <= 0) fFrequency = 0f;
                if (fPulseWidth <= 0) fPulseWidth = 0f;

                if (!rtc.CtlFrequency(fFrequency, fPulseWidth))
                {
                    Log.Write("SLD-200", "DrawCalibrationArc", "Laser Frequency 설정 실패");
                    return false;
                }
            }

            float fJumpSpeed = (float)Equipment.Scanner_Calibration_LaserJumpSpeed;
            float fMarkSpeed = (float)Equipment.Scanner_Calibration_LaserMarkSpeed;
            if (fJumpSpeed <= 0) fJumpSpeed = 0;
            if (fMarkSpeed <= 0) fMarkSpeed = 0;

            if (!rtc.CtlSpeed(fJumpSpeed, fMarkSpeed))
            {
                Log.Write("SLD-200", "DrawCalibrationArc", "Laser Speed 설정 실패");
                return false;
            }

            float fLaserOnDelay = (float)Equipment.Scanner_Calibration_LaserOnDelay;
            float fLaserOffDelay = (float)Equipment.Scanner_Calibration_LaserOffDelay;
            float fMarkDelay = (float)Equipment.Scanner_Calibration_MarkDelay;
            float fJumpDelay = (float)Equipment.Scanner_Calibration_JumpDelay;
            float fPolygonDelay = (float)Equipment.Scanner_Calibration_PolygonDelay;
            if (fLaserOnDelay <= 0) fLaserOnDelay = 0;
            if (fLaserOffDelay <= 0) fLaserOffDelay = 0;
            if (fMarkDelay <= 0) fMarkDelay = 0;
            if (fJumpDelay <= 0) fJumpDelay = 200;
            if (fPolygonDelay <= 0) fPolygonDelay = 0;

            if (!rtc.CtlDelay(fLaserOnDelay, fLaserOffDelay, fMarkDelay, fJumpDelay, fPolygonDelay))
            {
                Log.Write("SLD-200", "DrawCalibrationArc", "Laser Delay 설정 실패");
                return false;
            }

            rtc.ListBegin(laser, ListType.Auto);
            // 중심 기준 좌표로 시작점 계산
            float startX = -((cols - 1) * pitchX) / 2.0f;
            float startY = -((rows - 1) * pitchY) / 2.0f;

            for (int row = 0; row < rows; row++)
            {
                for (int col = 0; col < cols; col++)
                {
                    float centerX = startX + col * pitchX;
                    float centerY = startY + row * pitchY;

                    DrawCross(centerX, centerY, crossSize);
                }
            }

            rtc.ListEnd();
            rtc.ListExecute();

            bRtn = true;
            return bRtn;
        }

        /// <summary>
        /// 주어진 중심 좌표에 1mm 크기의 십자가를 그리는 함수
        /// </summary>
        /// <param name="centerX">십자가 중심의 X 좌표</param>
        /// <param name="centerY">십자가 중심의 Y 좌표</param>
        /// <param name="size">십자가의 크기 (mm)</param>
        private void DrawCross(float centerX, float centerY, float size)
        {
            float halfSize = size / 2;

            // 가로선 그리기
            rtc.ListJump(centerX - halfSize, centerY);
            rtc.ListMark(centerX + halfSize, centerY);

            // 세로선 그리기
            rtc.ListJump(centerX, centerY - halfSize);
            rtc.ListMark(centerX, centerY + halfSize);
        }


        /// <summary>
        /// Vacuum 관련 장치에 제품 유무 확인하는 함수 (Auto Run 시 체크하여 메세지 창 Pup-Up)
        /// 
        private void Check_VacuumParts_Module_Exist()
        {
            bool m_bLoader_Exist = false;
            bool m_bWorkStage_Exist = false;
            bool m_bUnloader_Exist = false;

            //  Loader Picker Vacuum On
            loader.loaderParameter.DO_Loader_Picker_Blow(false);
            loader.loaderParameter.DO_Loader_Picker_Vacuum((int)LoaderParameter.PickerVacuumPos.Inner, true);
            loader.loaderParameter.DO_Loader_Picker_Vacuum((int)LoaderParameter.PickerVacuumPos.Outer, true);

            //  Loader M-Aligner Vacuum On
            loader.loaderParameter.DO_Loader_Aligner_Blow((int)LoaderParameter.MAlignerVacuumPos.Center, false);
            loader.loaderParameter.DO_Loader_Aligner_Blow((int)LoaderParameter.MAlignerVacuumPos.Inner, false);
            loader.loaderParameter.DO_Loader_Aligner_Blow((int)LoaderParameter.MAlignerVacuumPos.Outer, false);
            loader.loaderParameter.DO_Loader_Aligner_Vacuum((int)LoaderParameter.MAlignerVacuumPos.Center, true);
            loader.loaderParameter.DO_Loader_Aligner_Vacuum((int)LoaderParameter.MAlignerVacuumPos.Inner, true);
            loader.loaderParameter.DO_Loader_Aligner_Vacuum((int)LoaderParameter.MAlignerVacuumPos.Outer, true);

            //  Work Stage
            workStageParameter.DO_Stage_Blow(false);
            workStageParameter.DO_Stage_Vacuum(true);
            ElectroPneumaticRegulatorComm_Pressure_Set(-60);

            //  Unloader Picker Vacuum On
            unloader.unloaderParameter.DO_Unloader_Picker_Blow(false);
            unloader.unloaderParameter.DO_Unloader_Picker_Vacuum((int)UnloaderParameter.PickerVacuumPos.Inner, true);
            unloader.unloaderParameter.DO_Unloader_Picker_Vacuum((int)UnloaderParameter.PickerVacuumPos.Outer, true);

            int m_nCount = 0;

            do
            {
                //  모든 공압을 켠 후 1초 정도 기다린다.
            } while (m_nCount++ < 1000);

            //  Loader Picker 에 Module 이 붙어있는지 체크
            if (loader.loaderParameter.DI_Loader_Picker_VacuumCheck((int)LoaderParameter.PickerVacuumPos.Inner) ||
                loader.loaderParameter.DI_Loader_Picker_VacuumCheck((int)LoaderParameter.PickerVacuumPos.Outer))
            {
                m_bLoader_Exist = true;
            }

            loader.loaderParameter.DO_Loader_Picker_Vacuum((int)LoaderParameter.PickerVacuumPos.Inner, false);
            loader.loaderParameter.DO_Loader_Picker_Vacuum((int)LoaderParameter.PickerVacuumPos.Outer, false);
            loader.loaderParameter.DO_Loader_Aligner_Vacuum((int)LoaderParameter.MAlignerVacuumPos.Center, false);
            loader.loaderParameter.DO_Loader_Aligner_Vacuum((int)LoaderParameter.MAlignerVacuumPos.Inner, false);
            loader.loaderParameter.DO_Loader_Aligner_Vacuum((int)LoaderParameter.MAlignerVacuumPos.Outer, false);

            //  Work Stage 에 Module 이 붙어있는지 체크
            if (workStageParameter.DI_Stage_Vacuum_Check())
            {
                m_bWorkStage_Exist = true;
            }

            workStageParameter.DO_Stage_Vacuum(false);
            ElectroPneumaticRegulatorComm_Pressure_Set(-1.3);

            //  Unloader Picker 에 Module 이 붙어있는지 체크
            if (unloader.unloaderParameter.DI_Unloader_Picker_VacuumCheck((int)UnloaderParameter.PickerVacuumPos.Inner) ||
                unloader.unloaderParameter.DI_Unloader_Picker_VacuumCheck((int)UnloaderParameter.PickerVacuumPos.Outer))
            {
                m_bUnloader_Exist = true;
            }

            unloader.unloaderParameter.DO_Unloader_Picker_Vacuum((int)UnloaderParameter.PickerVacuumPos.Inner, false);
            unloader.unloaderParameter.DO_Unloader_Picker_Vacuum((int)UnloaderParameter.PickerVacuumPos.Outer, false);


            if (m_bLoader_Exist)
            {
                MessageBox.Show("Loader Transfer Picker 에 제품 감지됨.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            if (m_bWorkStage_Exist)
            {
                MessageBox.Show("Work Stage 에 제품 감지됨.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            if (m_bUnloader_Exist)
            {
                MessageBox.Show("Unloader Transfer Picker 에 제품 감지됨.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        public bool DrawCalibrationArc(int rows, int cols, float pitchX, float pitchY)
        {
            if (rows <= 0 || cols <= 0)
                throw new ArgumentException("Rows and columns must be greater than zero.");

            bool bRtn = false;

            float crossSize = (float)Equipment.Scanner_Calibration_CrossMarkLength; //1.0f; //(float)markLength; 

            if (Equipment.Machine_LaserType_CO2)
            {
                float fFrequency = (float)Equipment.Scanner_Calibration_LaserFrequency;
                float fPulseWidth = (float)Equipment.Scanner_Calibration_LaserPulseWidth;    //2.6f;

                if (fFrequency / 2 <= fPulseWidth)
                    fPulseWidth = fFrequency / 2;
                if (fFrequency <= 0) fFrequency = 0f;
                if (fPulseWidth <= 0) fPulseWidth = 0f;

                if (!rtc.CtlFrequency(fFrequency, fPulseWidth))
                {
                    Log.Write("SLD-200", "DrawCalibrationArc", "Laser Frequency 설정 실패");
                    return false;
                }
            }

            float fJumpSpeed = (float)Equipment.Scanner_Calibration_LaserJumpSpeed;
            float fMarkSpeed = (float)Equipment.Scanner_Calibration_LaserMarkSpeed;
            if (fJumpSpeed <= 0) fJumpSpeed = 0;
            if (fMarkSpeed <= 0) fMarkSpeed = 0;

            if (!rtc.CtlSpeed(fJumpSpeed, fMarkSpeed))
            {
                Log.Write("SLD-200", "DrawCalibrationArc", "Laser Speed 설정 실패");
                return false;
            }

            float fLaserOnDelay = (float)Equipment.Scanner_Calibration_LaserOnDelay;
            float fLaserOffDelay = (float)Equipment.Scanner_Calibration_LaserOffDelay;
            float fMarkDelay = (float)Equipment.Scanner_Calibration_MarkDelay;
            float fJumpDelay = (float)Equipment.Scanner_Calibration_JumpDelay;
            float fPolygonDelay = (float)Equipment.Scanner_Calibration_PolygonDelay;
            if (fLaserOnDelay <= 0) fLaserOnDelay = 0;
            if (fLaserOffDelay <= 0) fLaserOffDelay = 0;
            if (fMarkDelay <= 0) fMarkDelay = 0;
            if (fJumpDelay <= 0) fJumpDelay = 200;
            if (fPolygonDelay <= 0) fPolygonDelay = 0;

            if (!rtc.CtlDelay(fLaserOnDelay, fLaserOffDelay, fMarkDelay, fJumpDelay, fPolygonDelay))
            {
                Log.Write("SLD-200", "DrawCalibrationArc", "Laser Delay 설정 실패");
                return false;
            }

            rtc.ListBegin(laser, ListType.Auto);
            // 중심 기준 좌표로 시작점 계산
            float startX = -((cols - 1) * pitchX) / 2.0f;
            float startY = -((rows - 1) * pitchY) / 2.0f;

            for (int row = 0; row < rows; row++)
            {
                for (int col = 0; col < cols; col++)
                {
                    float centerX = startX + col * pitchX;
                    float centerY = startY + row * pitchY;

                    // DrawArc 호출: 중심 좌표와 반지름, 시작 각도, 끝 각도를 전달
                    float radius = crossSize / 2.0f; // 반지름은 crossSize의 절반으로 설정
                    float startAngle = 0.0f;         // 시작 각도 (0도)
                    float endAngle = 360.0f;         // 끝 각도 (360도, 완전한 원)

                    DrawArc(centerX, centerY, radius, startAngle, endAngle);

                    //radius만 가지고 구하기.
                    //PointD pointD = new PointD(centerX, centerY);
                    //PointD startPoint = new PointD(centerX - radius, centerY);
                    //PointD endPoint = new PointD(centerX + radius, centerY);
                    //var angles = CalculateAngles(pointD, startPoint, endPoint);
                    //// DrawArc 호출: 중심 좌표와 반지름, 시작 각도, 끝 각도를 전달
                    //DrawArc(centerX, centerY, radius, (float)angles.startAngle, (float)angles.endAngle);

                }
            }

            rtc.ListEnd();
            rtc.ListExecute();
            bRtn = true;
            return bRtn;
        }

        /// <summary>
        /// FOV기준으로 cal 진행시 사용 함수.
        /// <summary>
        public bool DrawCalibrationArc(float fovWidth, float fovHeight, int rows, int cols, out float pitchX, out float pitchY)
        {
            pitchX = 0;
            pitchY = 0;

            if (rows <= 0 || cols <= 0)
                throw new ArgumentException("Rows and columns must be greater than zero.");

            bool bRtn = false;
            float crossSize = (float)Equipment.Scanner_Calibration_CrossMarkLength;  //1.0f; // 각 원의 지름을 1mm로 설정

            // pitch 자동 계산
            pitchX = (cols > 1) ? fovWidth / (cols - 1) : 0;
            pitchY = (rows > 1) ? fovHeight / (rows - 1) : 0;

            if (Equipment.Machine_LaserType_CO2)
            {
                float fFrequency = (float)Equipment.Scanner_Calibration_LaserFrequency;
                float fPulseWidth = (float)Equipment.Scanner_Calibration_LaserPulseWidth;    //2.6f;

                if (fFrequency / 2 <= fPulseWidth)
                    fPulseWidth = fFrequency / 2;
                if (fFrequency <= 0) fFrequency = 5000;
                if (fPulseWidth <= 0) fPulseWidth = 2.6f;

                if (!rtc.CtlFrequency(fFrequency, fPulseWidth))
                {
                    Log.Write("SLD-200", "DrawCalibrationArc", "Laser Frequency 설정 실패");
                    return false;
                }
            }

            float fJumpSpeed = (float)Equipment.Scanner_Calibration_LaserJumpSpeed;
            float fMarkSpeed = (float)Equipment.Scanner_Calibration_LaserMarkSpeed;
            if (fJumpSpeed <= 0) fJumpSpeed = 0; 
            if (fMarkSpeed <= 0) fMarkSpeed = 0; 

            if (!rtc.CtlSpeed(fJumpSpeed, fMarkSpeed))
            {
                Log.Write("SLD-200", "DrawCalibrationArc", "Laser Speed 설정 실패");
                return false;
            }

            float fLaserOnDelay = (float)Equipment.Scanner_Calibration_LaserOnDelay;
            float fLaserOffDelay = (float)Equipment.Scanner_Calibration_LaserOffDelay;
            float fMarkDelay = (float)Equipment.Scanner_Calibration_MarkDelay;
            float fJumpDelay = (float)Equipment.Scanner_Calibration_JumpDelay;
            float fPolygonDelay = (float)Equipment.Scanner_Calibration_PolygonDelay;
            if (fLaserOnDelay <= 0) fLaserOnDelay = 0;
            if (fLaserOffDelay <= 0) fLaserOffDelay = 0;
            if (fMarkDelay <= 0) fMarkDelay = 0;
            if (fJumpDelay <= 0) fJumpDelay = 200;
            if (fPolygonDelay <= 0) fPolygonDelay = 0;

            if (!rtc.CtlDelay(fLaserOnDelay, fLaserOffDelay, fMarkDelay, fJumpDelay, fPolygonDelay))
            {
                Log.Write("SLD-200", "DrawCalibrationArc", "Laser Delay 설정 실패");
                return false;
            }

            rtc.ListBegin(laser, ListType.Auto);

            float startX = -((cols - 1) * pitchX) / 2.0f;
            float startY = -((rows - 1) * pitchY) / 2.0f;

            for (int row = 0; row < rows; row++)
            {
                for (int col = 0; col < cols; col++)
                {
                    float centerX = startX + col * pitchX;
                    float centerY = startY + row * pitchY;

                    float radius = crossSize / 2.0f;
                    DrawArc(centerX, centerY, radius, 0.0f, 360.0f);
                }
            }

            rtc.ListEnd();
            rtc.ListExecute();
            bRtn = true;
            return bRtn;
        }

        private void DrawArc(float centerX, float centerY, float radius, float startAngle, float endAngle)
        {
            if (radius <= 0)
                throw new ArgumentException("Radius must be greater than zero.");

            // 원호의 sweepAngle 계산
            float sweepAngle = endAngle - startAngle;

            // 원호 시작점 계산.
            float startX = centerX + radius * (float)Math.Cos(startAngle * Math.PI / 180.0);
            float startY = centerY + radius * (float)Math.Sin(startAngle * Math.PI / 180.0);

            // 먼저 원호의 시작점으로 점프
            if (!rtc.ListJump(startX, startY))
            {
                throw new InvalidOperationException("Failed to jump to arc start position.");
            }

            // rtc.ListArc 호출
            if (!rtc.ListArc(centerX, centerY, sweepAngle))
            {
                throw new InvalidOperationException("Failed to draw arc using rtc.ListArc.");
            }
        }

        public static (double startAngle, double endAngle) CalculateAngles(PointD center, PointD startPoint, PointD endPoint)
        {
            // 시작 각도 계산
            double startAngle = Math.Atan2(startPoint.Y - center.Y, startPoint.X - center.X) * (180.0 / Math.PI);

            // 끝 각도 계산
            double endAngle = Math.Atan2(endPoint.Y - center.Y, endPoint.X - center.X) * (180.0 / Math.PI);

            // 각도를 0~360 범위로 변환
            if (startAngle < 0) startAngle += 360;
            if (endAngle < 0) endAngle += 360;

            return (startAngle, endAngle);
        }

        public double DustCollector_SetFrequence(double dRet_Freq)
        {

            //  주파수 단위가 0.01Hz 이므로, 100배 해야 함.
            dRet_Freq *= 100.0;

            //  숫자를 4자리 숫자로 고정
            string strFreq = dRet_Freq.ToString("0000");

            string strRet = this.ConvertDecimalToHex(strFreq);

            if (strRet != "NG")
            {
                this.m_bDustCollector_LowerPos_CommData_Received = false;
                this.m_strDustCollector_LowerPos_Comm_ReceivedData = "";

                this.DustCollectorComm_Send_Write((int)WorkStage.nDustCollector.DustCollector_Lower, "0005", 1, strRet);
            }

            return dRet_Freq;
        }


        /// <summary>
        /// 위치 좌표값 리스트로부터 배열의 Rows와 Columns를 계산합니다.
        /// </summary>
        public (int Rows, int Columns) CalculateArraySize(List<PointD> positions)
        {
            if (positions == null || positions.Count == 0)
            {
                MessageBox.Show("좌표값 리스트가 비어 있습니다.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            // 허용 오차 설정 (예: 0.01)
            double tolerance = 0.01;

            // X, Y 좌표값을 정렬하여 고유한 값 추출 (허용 오차 적용)
            var uniqueX = positions.Select(p => Math.Round(p.X / tolerance) * tolerance).Distinct().OrderBy(x => x).ToList();
            var uniqueY = positions.Select(p => Math.Round(p.Y / tolerance) * tolerance).Distinct().OrderBy(y => y).ToList();

            // 가로(Columns)와 세로(Rows) 계산
            int columns = uniqueX.Count;
            int rows = uniqueY.Count;

            return (rows, columns);
        }


        /// <summary>
        /// 특정 위치 좌표가 배열의 몇 번째 Row와 Column에 해당하는지 반환합니다.
        /// </summary>
        public (int Row, int Column) GetRowColumnFromPosition(List<PointD> positions, PointD target)
        {
            if (positions == null || positions.Count == 0)
            {
                MessageBox.Show("좌표값 리스트가 비어 있습니다.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            // 허용 오차 설정 (예: 0.01)
            double tolerance = 0.01;

            // X, Y 좌표값을 정렬하여 고유한 값 추출 (허용 오차 적용)
            var uniqueX = positions.Select(p => Math.Round(p.X / tolerance) * tolerance).Distinct().OrderBy(x => x).ToList();
            var uniqueY = positions.Select(p => Math.Round(p.Y / tolerance) * tolerance).Distinct().OrderBy(y => -y).ToList();

            //// X, Y 좌표값을 정렬하여 고유한 값 추출
            //var uniqueX = positions.Select(p => p.X).Distinct().OrderBy(x => x).ToList();
            //var uniqueY = positions.Select(p => p.Y).Distinct().OrderBy(y => -y).ToList();

            // Row와 Column 계산
            target.X = Math.Round(target.X, 4);
            target.Y = Math.Round(target.Y, 4);

            int row = uniqueY.IndexOf(target.Y);
            int column = uniqueX.IndexOf(target.X);

            if (row == -1 || column == -1)
            {
                MessageBox.Show("해당 좌표는 리스트에 존재하지 않습니다.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }

            return (row, column);
        }


        /// <summary>
        /// 1차원 배열의 인덱스를 주어진 row, column 크기의 2차원 배열에서 몇 번째 row와 column인지 계산합니다.
        /// </summary>
        /// <param name="index">1차원 배열의 인덱스</param>
        /// <param name="columns">배열의 column(열) 개수</param>
        /// <returns>row와 column 위치</returns>
        public (int Row, int Column) GetRowColumnFromIndex(int index, int columns)
        {
            int row = 1;    // 몇 번째 행인지 계산
            int column = 1; // 몇 번째 열인지 계산

            if (columns <= 0)
            {
                //throw new ArgumentException("열의 개수는 0보다 커야 합니다.", nameof(columns));
            }
            else
            {
                row = index / columns;    // 몇 번째 행인지 계산
                column = index % columns; // 몇 번째 열인지 계산
            }
            return (row, column);
        }

        public (int Row, int Column) GetRegionRowColumnFromIndex(int index, int region_columns)
        {
            int region_row = 1;    // 몇 번째 행인지 계산
            int region_column = 1; // 몇 번째 열인지 계산

            if (region_columns <= 0)
            {
                //throw new ArgumentException("열의 개수는 0보다 커야 합니다.", nameof(columns));
            }
            else
            {
                region_row = index / region_columns;    // 몇 번째 행인지 계산
                region_column = index % region_columns; // 몇 번째 열인지 계산
            }
            return (region_row, region_column);
        }


