                    {
                        switch (typeSpeed)
                        {
                            case Type_Motor_Speed.Fine:
                                dVelocity = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Jog_Speed_Fine;
                                dAcc = Equipment.stAxisParam[(int)WorkStage.nAxis.Z].Common_Acceleration_Fine;
